insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-5-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C5'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Notamment en lien avec SF4, par ex : - « Carnaval des animaux », C. Saint-Saëns. - « Pierre et le Loup », S. Prokofiev. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-5-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C5'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Notamment en lien avec SF2, par ex : - « Marche de Radetzky », J. Strauss. - « L’Arlésienne », G. Bizet. - « Valse n°2 », D. Shostakovich. - « Sarabande », G.F. Haendel. - « Fanfare pour le carrousel royal », J.-B. Lully. - Répertoire musical lié au quotidien des élèves. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-5-4', (select id from public.curriculum_item where version = '2022' and code = 'EA-C5'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', '▶ Expression : - Chants traditionnels (par ex : « Ah vous dirais-je maman », « J’ai du bon tabac », « Au clair de la lune », repris dans les « Fossiles » du « Carnaval des animaux »...). - Chants à danser (par ex : « La p’tite hirondelle », « Face à face » Y. Berger...). - Chansons /Spectacles « Jeune public »* (voir sélection « Chansons à l’école »). - Répertoire musical lié au quotidien des élèves. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-5-5', (select id from public.curriculum_item where version = '2022' and code = 'EA-C5'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique - Les plasticiens* de la couleur (par ex : P. Mondrian, Y. Klein, H. Matisse, S. Delaunay, M. Rothko, A. Derain…). - Le graphisme (par ex : art aborigène, J. Dubuffet, K. Haring, J. Mirõ, dessinateurs de BD, illustrateurs...). - Le modelage* (par ex : N. de Saint Phalle, P. Picasso, M.-P. Jan...).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-6-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C6'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Suite aux visites et observations de préférence in situ, nommer : - un lieu culturel de son environnement proche ; - des éléments du patrimoine* local ; - des objets de diverses cultures, liés à la vie quotidienne.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-7-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Identifier et nommer les différents rythmes du corps en mouvement : rythme cardiaque, rythme de la marche, rythme de la respiration…', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-7-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Identifier et décrire la pulsation* avec ses mots.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-7-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Décrire, avec ses mots, des rythmes* dans un visuel ou dans son environnement immédiat (répétitions de couleurs, de lignes…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-7-4', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Identifier une variété de formes dans son environnement proche.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P1-8-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Décrire : - l’expressivité du corps : les mouvements, les postures ; - l’expressivité du visage, la direction du regard.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
