insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-33-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C33'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Camille et Julie Berthollet. - « Gymnopédies », E. Satie. - « Concerto d’Aranjuez », pour guitare et orchestre, J. Rodrigo. - « Bambino », Dalida, version OSS 117. - « Imagine », J. Lennon. - Le « Canon », J. Pachelbel. - Oum Kalthoum. - « Pierre et le Loup », S. Prokofiev. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
