insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-33-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C33'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique - La représentation du mouvement en art (par ex : C. Twombly, K. Hokusai, V. Vasarely, W. Leblanc, les futuristes Italiens, E. Degas…). - Les artistes illustrateurs (par ex : H. Davies, R. Tasker, K. Canby, J.-M. Folon, A. Warhol...). - La géométrie dans l’art (par ex : D. Buren, S. Delaunay, V. Vasarely, pavages islamiques, motifs hindous, vitraux…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-6-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C6'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Suite aux visites et observations de préférence in situ, décrire : - un lieu culturel et de spectacle (théâtre, concert, cinéma, chapiteau…) ; - des éléments du patrimoine* matériel belge ; - des œuvres et/ou objets de cultures diverses.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-7-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Décrire la temporalité entre les danseurs ou dans le jeu* théâtral : répétition, succession, alternance, enchainement…', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-7-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Identifier et définir la pulsation* et le rythme*.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-7-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Exemplifier la représentation en miroir.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-8-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Décrire : - la voix : intensité, hauteur, pause, respiration (voir P1 et P2 en expression musicale) ; - la position du corps (équilibre/déséquilibre, transferts d’appuis…) ; - l’énergie des mouvements (lourd/léger, aquatique, aérien…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-8-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Définir la ligne mélodique*, la direction sonore (notes ascendantes, répétées et descendantes).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P3-8-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Décrire les qualités et les caractéristiques des outils et des matériaux (poudre, liquide, épais, souple, transparent…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
