insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P4-38-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C38'), 'primaire', array['P4']::text[], 'Éducation culturelle et artistique', 'attendu', 'Le Sacre du printemps, les ballets contemporains de M. Béjart, A. Alonso...).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P4-39-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C39'), 'primaire', array['P4']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale ▶ Écoute : Notamment en lien avec S2 (aérophones*), par ex : - Marches pour orchestres d’harmonie, Brassband… - « Petite symphonie pour vents », C. Gounod… - Airs de carnavals… - « What a Wonderful World », L. Armstrong… - « Piccolo, Saxo et Cie », J. Broussolle et A. Popp… ▶ Expression : Notamment en lien avec S2 (éléments constitutifs de la musique et canons), par ex : - « La Mélodie du bonheur », version J. Andrews. - « Gammes et arpèges » (Film « Les Aristochats », Disney)… - Canons et chants du monde (par ex : « Tongo », « Funga Alafia », « Tuwe Tuwe », « Obwisana »... - Canons à trois voix (par ex : « Banuwa round », « Sambalelé », « Django », « Mes petits souliers », H. Dès)…', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P4-39-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C39'), 'primaire', array['P4']::text[], 'Éducation culturelle et artistique', 'attendu', 'Notamment en lien avec SF2, par ex : - Ostinato*: « We Will Rock You », Queen… - « Boléro », M. Ravel… - Répertoire musical lié au quotidien des élèves. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P4-39-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C39'), 'primaire', array['P4']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique - Des plasticiens* du geste (par ex : M.H. Vieira da Silva, J. Pollock, H. Hartung…). - Des artistes assembleurs (par ex : L. de Vinci, Panamarenko, les artistes de l’Arte Povera…). - L’art pariétal (par ex : Grottes de Lascaux, Grottes de Chauvet, les géoglyphes, J.-L. Moerman…). - La sculpture (par ex : A. Calder, J. Tinguely, P. Bury, sculptures grecques, A. Rodin, C. Claudel, A. Giacometti…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P4-6-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C6'), 'primaire', array['P4']::text[], 'Éducation culturelle et artistique', 'attendu', 'Suite aux visites et observations de préférence in situ, expliquer : - une œuvre d’art ; - un musée ou une exposition ; - des éléments du patrimoine* immatériel (voir références) ; - des traditions (coutumes) d’origines diverses.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
