insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-1-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C1'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Sélectionner au moins un exemple par mode d’expression.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-1-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C1'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'En expression musicale, choisir au moins une référence pour l’écoute et une pour l’expression.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-42-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C42'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', '- Œuvres issues du théâtre « Jeune Public* ». - Œuvres issues de la danse « Jeune Public ».', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-43-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C43'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale ▶ Écoute :', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-44-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C44'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Notamment en lien avec S2 (membranophones*/ idiophones*), par ex : - « Stomp ». - « Batucada brésilienne », percussions africaines, beatbox - « Casse-noisette, danse de la fée dragée », P. Tchaikovski. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-45-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C45'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', '▶ Expression :', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-46-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C46'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Notamment en lien avec S2, par ex : - Chants à thèmes (par ex : « African Tour », F. Cabrel, « Je suis un homme », Zazie, « Lily », P. Perret, « Pour les enfants du monde entier », Y. Duteil, « Il en faut peu pour être heureux », Disney, « Akuna matata », Disney…). - Répertoire musical lié au quotidien des élèves. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-46-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C46'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique - De la lumière dans l’art (par ex : l’art gothique, l’impressionnisme, Le Caravage, Rembrandt, J. Vermeer, A.V. Janssens, G. de La Tour…). - La photographie (par ex : M. Parr, R. Doisneau, H. Cartier-Bresson, E. Muybridge, Y. Arthus-Bertrand...). - Le cinéma (par ex : G. Méliès, F.W. Murnau, extraits du cinéma muet et hollywoodien…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-6-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C6'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Suite aux visites et observations de préférence in situ, présenter : - un site archéologique ; - des éléments du patrimoine* immatériel ; - un mythe ou une légende.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-7-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Expliquer le déroulement du temps dans la représentation (par ex : chronologie, flash-back, ellipse temporelle…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-7-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Différencier la pulsation* et le rythme*.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-7-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Caractériser une image fixe* et une image* en mouvement.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-8-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Identifier : - différentes techniques vocales et de diction (accent tonique, articulation, intonation, prononciation...) ; - l’énergie des mouvements : le tonus musculaire (par ex : tension/ détente, flexion/extension...).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-8-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Décrire des éléments constitutifs du langage musical (partition, portée, gamme, clé de sol…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-8-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Distinguer : - le croquis, le dessin ; - la photographie numérique ; - les outils graphiques spécialisés (pinceaux, couteaux, spatule, rouleau, brosse, éponge...).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-9-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C9'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Comparer différentes occupations de l’espace et du plateau (par ex : le regroupement, l’équilibre/déséquilibre, la division des espaces scéniques…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-9-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C9'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Décrire des formes musicales au travers de chansons contemporaines, traditionnelles ou extraits classiques.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-9-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C9'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Distinguer : - le fond, la forme, la mise en page, le plan, le format, les échelles et proportions ; - les volumes simples.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-47-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C47'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Comparer des genres de : - jeux* (par ex : comédie, tragédie, comédie musicale, seul en scène…) ; - danses (par ex : indiennes, africaines, contemporaines, tango, flamenco…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P5-47-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C47'), 'primaire', array['P5']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Reconnaitre visuellement et auditivement des membranophones* et des idiophones* d’ici ou d’ailleurs.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
