insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P6-51-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C51'), 'primaire', array['P6']::text[], 'Éducation culturelle et artistique', 'attendu', 'Notamment en lien avec S2 (couleurs/timbres*), par ex : - « Young Person’s Guide to the Orchestra », B. Britten. - « Air de la reine de la nuit », W.A. Mozart. - « 5e Symphonie », L. Beethoven. - « Symphonie des jouets », L. Mozart. - « Demonstrates the Power of the Pentatonic Scale », B. McFerrin. - « Duo des chats » (air pour deux sopranos), G. Rossini. - « Barocco Andino ». - « Stripsody », C. Berberian. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
