insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-P6-8-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['P6']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Décrire : - la chorégraphie/la structure de la phrase dansée (par ex : la combinaison des gestes, des déplacements...) ; - le jeu* masqué (ses particularités, ses implications sur la posture...) ; - le rôle des partenaires, les points de contacts ou les types d’interactions dans le mouvement ; - les parties du corps initiatrices du mouvement.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
