insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-56-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C56'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', '- « Chanson de Roland » >< « Enea volare », Era (Film « Les Visiteurs ») (Moyen Âge). - « Tourdion », anonyme >< « Conquest of Paradise », Vangelis (Film « 1492 Christophe Colomb ») (Renaissance). - « Marche des Turcs », J.-B. Lully >< « Lascia ch’io pianga », Haendel (Film « Farinelli ») (Période baroque). - « La Surprise », Haydn >< « L’Enlèvement au sérail », W.A. Mozart (Film « Amadeus ») (Période classique). - « La Chevauchée des Walkyries », R. Wagner >< « Also sprach Zarathustra », R. Strauss (Film « 2001 L’Odyssée de l’espace ») (Période romantique). - « Le Sacre du printemps », I. Stravinsky >< « O Fortuna », C. Orff (Film « Excalibur ») (Période moderne). - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-56-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C56'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', '▶ Expression : Notamment en lien avec S2 et C2, par ex : - « Quand la musique est bonne », J.-J. Goldman. - « Oh Happy Day ». - « Armstrong », C. Nougaro, version Maurane. - « Monopolis », M. Berger (« Starmania »). - « Les sans-papiers », R. Cocciante (« Notre-Dame de Paris »)… - Répertoire musical lié au quotidien des élèves. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-56-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C56'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique - La perspective dans l’art (par ex : Canaletto, Michel- Ange, P. Delvaux, L.B. Alberti, A. Dürer, D. Francesca, Masaccio, A. Gentileschi…). - L’art urbain (par ex : J.-M. Basquiat, Banksy, K. Haring, JR, Nano 4814, Edgar Flores, Flip, E. Koba...). - L’abstraction (par ex : V. Kandinsky, K. Malevitch, J. Pollock, J. Delahaut, P. Soulages...). - La figuration (par ex : S. Valadon, M. Laurencin, P.P. Rubens, P. Bruegel, G. Courbet, D. Hockney…). - Les illustrateurs/dessinateurs BD (par ex : C. Ponti, C. Bretécher, M. de Radiguès, L. Gaume, Uderzo…). - Cinéma moderne et contemporain (Nouvelle Vague, œuvres* d’aujourd’hui, cinéma belge…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-6-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C6'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Suite aux visites in situ et aux recherches documentaires, analyser : - les informations recueillies ; - son répertoire d’objets de cultures, d’époques et de pays différents.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-7-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Analyser la scansion* dans un texte poétique.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-7-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Identifier les structures rythmiques dans la représentation : dans l’éclairage, la voix et les déplacements des comédiens, la pulsation* et le rythme* des mouvements.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-7-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Identifier le caractère binaire ou ternaire d’un morceau instrumental ou d’une chanson.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-7-4', (select id from public.curriculum_item where version = '2022' and code = 'EA-C7'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Analyser la composition (équilibre, harmonie, symétrie, vides/pleins…) dans des images* fixes et des images en mouvement.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-8-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression française et corporelle Analyser : - la chorégraphie (par ex : le détournement* des gestes du quotidien, la symbolique du geste…) ; - l’adresse et la mise en voix des personnages.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-8-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression musicale Identifier dans une partition des indicateurs d’intensité, de tempo* et d’interprétation (par ex : p, f, mp/mf, cresc, decresc, allegro, lento, moderato, legato, staccato…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S1-8-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C8'), 'primaire', array['S1']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique Identifier des techniques de collages et d’assemblages dans des œuvres* appartenant à l’art abstrait.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
