insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S2-61-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C61'), 'primaire', array['S2']::text[], 'Éducation culturelle et artistique', 'attendu', '- Théâtre lié à l’actualité culturelle. - Spectacles pluridisciplinaires (par ex : Light danse, Enra…). Expression musicale ▶ Écoute :', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S2-62-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C62'), 'primaire', array['S2']::text[], 'Éducation culturelle et artistique', 'attendu', 'Notamment en lien avec S2 et SF2, par ex : - « Le matin » de « Peer Gynt », E. Grieg. - « Sicilienne », G. Fauré. - « Young Person’s Guide to the Orchestra », B. Britten. - Rondeau « Abdelazar », H. Purcell. - « La Brabançonne », versions et instrumentations différentes. - « Mistral gagnant », versions Renaud, Louane, L. Fabian, Cœur de Pirate... - « Ne me quitte pas », versions J. Brel, Stromae, C. Dion. - « Mon amant de Saint-Jean », versions P. Bruel, L. Delyle. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S2-62-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C62'), 'primaire', array['S2']::text[], 'Éducation culturelle et artistique', 'attendu', '▶ Expression : Notamment en lien avec C4, par ex : - « Mistral gagnant », Renaud. - « L’Envie », J. Hallyday. - « Un Été de porcelaine », M. Schuman. - « Tarentelle », Y. Duteil. - Répertoire musical lié au quotidien des élèves. - …', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S2-62-3', (select id from public.curriculum_item where version = '2022' and code = 'EA-C62'), 'primaire', array['S2']::text[], 'Éducation culturelle et artistique', 'attendu', 'Expression plastique - Le détournement* (par ex : B. Kruger, G. Penone, le Land art, M. Duchamp...). - Les calligraphies (par ex : l’art chinois, l’art japonais, l’art musulman, les parchemins médiévaux...). - Les installations* (par ex : A. Messager, L. Bourgeois, K. Geers, T. Margolles, J. Beuys, D. Hirst…). - La BD belge (par ex : J.-C. Servais, J. Van Hamme, Hergé, Franquin, F. Schuiten…).', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S2-6-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C6'), 'primaire', array['S2']::text[], 'Éducation culturelle et artistique', 'attendu', 'Suite aux visites in situ et aux recherches documentaires, catégoriser : - les informations recueillies ; - les objets de culture, en lien avec l’évolution scientifique, technique et technologique.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
