insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-78-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C78'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Apprendre à apprendre requiert que les élèves développent les opérations mentales de base susceptibles de les aider à organiser leurs apprentissages et la ré-', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-79-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C79'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'alité qui les entoure. Les élèves sont également amenés à prendre conscience, analyser et réguler ces opérations et en particulier à maitriser les principales compétences méthodologiques du « métier d’élève ». Enfin, ils sont incités à développer un environnement personnel d’apprentissage, c’est-à-dire un ensemble organisé de ressources et d’outils physiques et/ou numériques à mobiliser et à agencer pour apprendre.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-80-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C80'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Décoder les fondamentaux des trois modes d’expressions artistiques, par des pratiques et au travers d’œuvres* de genres, de cultures et d’époques différentes. (C 2) Classer des objets culturels selon des critères. (SF 3)', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-81-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C81'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Décoder les fondamentaux des trois modes d’expressions artistiques, par des pratiques et au travers d’œuvres* de genres, de cultures et d’époques différentes. (C 2) Observer* de manière multisensorielle : regarder, écouter, gouter, sentir toucher, apprécier*. (SF 1) Classer des objets culturels selon des critères. (SF 3) Interroger le contexte*, la fonction*, le sens d’éléments culturels. (SF 3)', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
