insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-85-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C85'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Développer une pensée critique et complexe requiert de recourir à des catégories d’analyse multiples pour lutter contre les généralisations, de développer une appréhension des causalités circulaires ainsi que de trouver, traiter et évaluer des sources d’informations fiables, quel qu’en soit le support, y compris numérique.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
