insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-89-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C89'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'l’engagement, ainsi que la capacité de programmer et de gérer des projets en vue de la réalisation d’objectifs. Il s’agit de pouvoir transformer des idées en actes. On peut dire qu’il y a créativité lorsqu’au terme d’une réalisation les élèves proposent une (piste de) solution nouvelle (pertinente, efficace et originale) ou lorsque leur processus de recherche démontre leur capacité à produire des idées ou des comportements divergents.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
