insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-94-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C94'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Créer collectivement et/ou individuellement. (C 4) Utiliser des outils, des instruments, le corps, l’image*, le son et la voix. (SF 2)', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-94-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C94'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'S’orienter repose sur la connaissance de soi, mais aussi sur une découverte du monde extérieur et de l’éventail des possibles qu’il offre en ma-', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-95-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C95'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'tière de filières d’études et de métiers ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignées à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-96-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C96'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Le référentiel sera l’occasion de découvrir une diversité de milieux professionnels des arts et de la culture : les secteurs culturels, la conservation et la valorisation du patrimoine* (matériel et immatériel), l’actualité culturelle, l’interculturalité,', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-97-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C97'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'l’exploration de l’environnement immédiat culturel et artistique, la création contemporaine… Il offrira aussi aux élèves des occasions de découvrir des métiers :', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-98-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C98'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', '- métiers techniques et de l’ombre : bruiteur/illustrateur sonore, caméraman, costumier, décorateur, éclairagiste, machiniste de plateau, maquilleur, monteur, régisseur de spectacles, technicien effets spéciaux, technicien son… - arts plastiques et visuels : caricaturiste, dessinateur, céramiste, critique d’art, graphiste, illustrateur, peintre, photographe, sculpteur…', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-99-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C99'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', '- musique : chanteur, choriste, chef de chœur, chef d’orchestre, musicien, instrumentiste, professeur… - mise en valeur du patrimoine* : animateur patrimoine, antiquaire, archéologue, commissaire d’exposition, commissaire-priseur, conservateur du patrimoine, expert en art, galeriste, guide touristique, historien de l’art, muséographe,', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-100-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C100'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'restaurateur d’œuvres d’art… Les apprentissages et découvertes des élèves constitueront des opportunités pour mettre en relation des métiers ou des sphères professionnelles avec les options et filières d’études de l’après tronc commun, et/ou avec des parcours d’études ou de formations et/ou avec des projets personnels.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-100-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C100'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Relevant davantage d’un savoir-agir, il s’agit ici pour l’élève de rassembler, d’articuler et d’incarner ce qu’il a appris sur lui-même et sur les autres, ce qu’il', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-101-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C101'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'a appris du monde scolaire, de la diversité des filières et options scolaires qui s’ouvrent après le tronc commun et ce qu’il connait du monde des activités', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-102-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C102'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'professionnelles, de manière à se forger une vision de l’avenir et à se mettre en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, gouts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à « construire leur vie ». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-103-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C103'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Les visites, les rencontres et les partenariats (C 1) demeurent des occasions de découvrir et de développer des affinités avec le monde culturel. Simultanément, les activités de création(s) proposées au sein du référentiel (C 4) favorisent l’émergence et la réalisation de projets artistiques, qu’ils soient mis en œuvre en autonomie ou collectivement.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-104-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C104'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Le référentiel ECA, dans sa globalité, contribue à « casser » les stéréotypes liés notamment au choix des filières artistiques, aux stéréotypes de genre (par exemple, dans les domaines de la danse et du chant), aux stéréotypes sociaux, aux choix et gouts personnels…', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-105-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C105'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'La découverte du monde culturel et artistique et de son fonctionnement incite les élèves à réfléchir et à poser des choix en termes de poursuite de leur parcours après le tronc commun vers des filières artistiques.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-106-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C106'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'L’interdépendance entre les trois composantes du référentiel ECA « Connaitre – Pratiquer – Rencontrer », permet de développer un cadre stimulant qui leur ouvre de multiples possibilités.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-107-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C107'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'La démarche artistique est porteuse en elle-même de réadaptations de ses propres choix qui sous-tendent toute évolution personnelle et professionnelle.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-108-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C108'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Le savoir-faire 3 « Interroger le contexte*, la fonction* et le sens d’éléments culturels » offre des opportunités multiples pour argumenter les choix posés.', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-109-1', (select id from public.curriculum_item where version = '2022' and code = 'EA-C109'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Utiliser le vocabulaire exprimant des positions absolues : à côté de, contre, à l’intérieur, à Identifier : l’extérieur, entre, sous, sur, dans, hors, autour de,', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EA-S3-109-2', (select id from public.curriculum_item where version = '2022' and code = 'EA-C109'), 'primaire', array['S3']::text[], 'Éducation culturelle et artistique', 'attendu', '- la direction des déplacements (gauche/droite, face à face, dos à dos. (S) avant/arrière) ; Utiliser le vocabulaire exprimant des positions - le positionnement des corps dans l’espace (par relatives (liées au regard) : devant, derrière, à droite, ex : face à face, côte à côte, l’un derrière l’autre, en à gauche, en haut, en bas, au-dessus, en dessous, ligne, en cercle…) ; en face de. (S) - les niveaux de déplacement (haut/moyen/bas). (S) Utiliser le vocabulaire décrivant un déplacement, tel que : monter, descendre, avancer, reculer, s’éloigner, se rapprocher, faire demi-tour… (S)', 'Référentiel d''Éducation culturelle et artistique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-cult-art-ECA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
