insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-212-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C212'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Se connaitre et s’ouvrir aux autres requièrent de développer une conscience de soi et de l’autre, du temps et de l’espace ainsi que du collectif.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-213-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C213'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Exemples de contenus ou d’attendus contributifs GSS4 Construire une image positive de soi, développer son sentiment de compétence et plus largement son estime de soi à adopter un mode de vie sain et actif, dans et en dehors de l’école : Identifier ses forces en activité physique. (C, P3-P4) Énoncer ses forces en activité physique. (C, P5) HSC1 Respecter des règles convenues dans l’intérêt du groupe et de chacun en fonction du but à atteindre : Assumer différents rôles et responsabilités. (SF, P1 à P6) Assumer tous les rôles. (SF, S1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-214-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C214'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'HSC3 Interagir positivement avec ses partenaires. S’affirmer en respectant les autres (assertivité, vigilance aux stéréotypes…) : Respecter les autres et le milieu. (SF, P1-P2) Adopter un comportement fair-play. (C, P1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-215-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C215'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'GSS3 Identifier ses émotions, mobiliser des techniques de gestion des émotions et du stress : Verbaliser l’effet croisé de ses émotions et de celles des autres sur la dynamique du groupe. (SF, P5 à S3) Mobiliser les techniques expérimentées pour gérer ses émotions et ses stress. (SF, S1 à S3) GSS4 Construire une image positive de soi, développer son sentiment de compétence et plus largement son estime de soi à adopter un mode de vie sain et actif, dans et en dehors de l’école : Admettre les différences en évitant les stéréotypes de genre, morphologiques, de capacités, médicaux, comportementaux, intellectuels… en rapport à l’engagement dans l’activité. (SF, P5-P6) HSC1 Respecter des règles convenues dans l’intérêt du groupe et de chacun en fonction du but à atteindre : Se comporter en respectant des règles. (C, P1 à S3) Participer à l’élaboration et au respect de règles communes. (SF, P3 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-216-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C216'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'GSS1 Adopter un style de vie sain et actif, être activement responsable de sa condition physique : Identifier les possibilités d’activités physiques durant la journée. (C, P1-P2) Planifier ses activités hebdomadaires pour atteindre les recommandations de santé. (C, P6) Mettre en pratique et ajuster son planning personnel d’activités physiques. (C, S1-S2) Mettre en pratique les principes de la condition physique de façon à mener une vie saine et active. (C, S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-217-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C217'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'HSC2 Contribuer activement à la construction d’une réalisation commune : Décider et agir dans une action commune pour se mettre au service de l’action collective. (C, P5 à S2)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-217-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C217'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Apprendre à apprendre requiert que les élèves développent les opérations mentales de base susceptibles de les aider à organiser leurs apprentissages et la ré-', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-218-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C218'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'alité qui les entoure. Les élèves sont également amenés à prendre conscience, analyser et réguler ces opérations et en particulier à maitriser les principales compétences méthodologiques du « métier d’élève ». Enfin, ils sont incités à développer un environnement personnel d’apprentissage, c’est-à-dire un ensemble organisé de ressources et d’outils physiques et/ou numériques à mobiliser et à agencer pour apprendre.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-219-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C219'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'GSS1 Adopter un style de vie sain et actif, être activement responsable de sa condition physique : Reconnaitre ses capacités et continuer à s’engager dans les activités physiques proposées', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-220-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C220'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'avec l’objectif de maintenir et d’améliorer sa condition physique et son bien-être. (C, S1 à S3) Mettre en pratique et ajuster son planning personnel d’activités physiques. (C, S1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-220-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C220'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'GSS4 Construire une image positive de soi, développer son sentiment de compétence et plus largement son estime de soi à adopter un mode de vie sain et actif, dans et en dehors de l’école : Identifier dans l’année ses propres réussites, même partielles, à adopter un mode de vie sain et actif. (SF, P5-P6) Réaliser une trace de ses réussites à adopter un mode de vie sain et actif. (SF, S1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-221-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C221'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Développer une pensée critique et complexe requiert de recourir à des catégories d’analyse multiples pour lutter contre les généralisations, de développer une appréhension des causalités circulaires ainsi que de trouver, traiter et évaluer des sources d’informations fiables, quel qu’en soit le support, y compris numérique.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-222-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C222'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'GSS5 Exercer sa pensée critique sur divers sujets liés à la santé et au bien-être : S’interroger et formuler des questions sur divers sujets liés à la santé. (C, P1 à S3) Exprimer une opinion argumentée sur un sujet lié à la santé et au bien-être. (C, S3) Repérer des images stéréotypées du corps véhiculées par la société (médias, réseaux sociaux…). (SF, P5 à S3) Identifier des effets négatifs sur la santé de la sédentarité et des excès liés à certaines', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-222-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C222'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'pratiques sportives (dopage, compléments alimentaires, boissons énergisantes…). (S, S1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-222-3', (select id from public.curriculum_item where version = '2022' and code = 'EP-C222'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'L’esprit d’entreprendre suppose de l’initiative, de la créativité, de l’innovation et de', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-223-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C223'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'l’engagement, ainsi que la capacité de programmer et de gérer des projets en vue de la réalisation d’objectifs. Il s’agit de pouvoir transformer des idées en actes. On peut dire qu’il y a créativité lorsqu’au terme d’une réalisation les élèves proposent une (piste de) solution nouvelle (pertinente, efficace et originale) ou lorsque leur processus de recherche démontre leur capacité à produire des idées ou des comportements divergents.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-224-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C224'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Exemples de contenus ou d’attendus contributifs HME5 S’exprimer et communiquer à l’aide de son corps : Improviser sur un thème, une idée, une musique… (SF, P1-P2) Improviser seul ou en partenariat sur un thème, une idée, une musique… (SF, P3-P4) Créer une situation d’expression corporelle, une chorégraphie sur une idée, un thème… (SF, P5 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-225-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C225'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'HSC2 Contribuer activement à la construction d’une réalisation commune : Décider et agir dans une action commune pour se mettre au service de l’action collective. (C, P5 à S2) Participer à l’élaboration de stratégies collectives en fonction du but à atteindre. (C, S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-226-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C226'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'HSC1 Respecter des règles convenues dans l’intérêt du groupe et de chacun en fonction du but à atteindre : Participer à l’élaboration de règles communes. (SF, P3 à P6)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-226-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C226'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'S’orienter repose sur la connaissance de soi, mais aussi sur une découverte du monde extérieur et de l’éventail des possibles qu’il offre en ma-', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-227-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C227'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'tière de filières d’études et de métiers, ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignées à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-228-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C228'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Les savoirs, savoir-faire et compétences suivants seront des occasions de découvrir une diversité de métiers : • Créer une situation d’expression corporelle, une chorégraphie sur une idée, un thème… (SF, HME5, P5 à S3) Apprécier la production de pairs et la sienne. (SF, HME5, P5 à S3) Métiers artistiques (comédien, danseur, circassien…).', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-229-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C229'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', '• La physiologie de l’effort physique. (S, SF, C, GSS1, P1 à S3) Les principes de manutention et les postures appropriées aux positions assise et debout. (SF, GSS2, P1 à S3) Les grands principes liés à une bonne hygiène de vie (hygiène, alimentation, hydratation, sommeil, activité physique, évitement de la sédentarité…). (S, SF, C, GSS1, P1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-230-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C230'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Les effets négatifs sur la santé de la sédentarité et des excès liés à certaines', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-231-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C231'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'pratiques sportives (dopage, compléments alimentaires, boissons énergisantes, surentrainement…). (S, GSS5, P1 à S3) Les techniques de gestion des émotions et du stress. (SF, GSS3, P1 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-232-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C232'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Métiers de la santé (médecin, diététicien, kinésithérapeute, ergothérapeute, psychologue…). Métiers du sport (entraineur et/ou moniteur sportif, sportif de haut niveau, préparateur physique, coach individuel…). • Les composantes de la sécurité en milieux naturel, urbain et aquatique. (S, SF, C, GSS2, de P1 à S3) Métiers de la sécurité (secouriste, maitre-nageur…).', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-232-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C232'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Les apprentissages et découvertes des élèves constitueront des opportunités pour mettre en relation des métiers ou des sphères professionnelles avec les options et filières d’études de l’après tronc commun, et/ou avec des parcours d’études ou de formations et/ou avec des projets personnels.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-232-3', (select id from public.curriculum_item where version = '2022' and code = 'EP-C232'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Relevant davantage d’un savoir-agir, il s’agit ici pour l’élève de rassembler, d’articuler et d’incarner ce qu’il a appris sur lui-même et sur les autres, ce qu’il', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-233-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C233'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'a appris du monde scolaire, de la diversité des filières et options scolaires qui s’ouvrent après le tronc commun et ce qu’il connait du monde des activités', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-234-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C234'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'professionnelles, de manière à se forger une vision de l’avenir et à se mettre en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, gouts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à «construire leur vie». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-235-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C235'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Par une prise de conscience progressive des facteurs susceptibles d’influencer les habitudes de vie positivement ou négativement, l’élève apprend à poser des choix lui permettant de développer et de préserver sa santé. Il apprend à poser un regard critique sur les stéréotypes et préjugés véhiculés en cette matière par la société :', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-235-2', (select id from public.curriculum_item where version = '2022' and code = 'EP-C235'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Mettre en pratique et ajuster son planning personnel d’activités physiques. (C, GSS1,', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-235-3', (select id from public.curriculum_item where version = '2022' and code = 'EP-C235'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'S1 à S3) Identifier des facteurs qui peuvent motiver ou décourager une participation quotidienne aux activités physiques. (S, GSS4, S1 à S3) Adapter son comportement à la situation pour préserver son intégrité physique et celle des autres. (C, GSS2, P5 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-235-4', (select id from public.curriculum_item where version = '2022' and code = 'EP-C235'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Nager en autonomie en connaissant la distance que l’on est capable de parcourir. (C, GSS2, S3) Distinguer les postures favorables ou nuisibles liées à l’activité pratiquée. (S, GSS2, S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('EP-S3-236-1', (select id from public.curriculum_item where version = '2022' and code = 'EP-C236'), 'primaire', array['S3']::text[], 'Éducation physique', 'attendu', 'Prendre conscience et analyser les influences positives et négatives du numérique sur sa pratique physique. (C, GSS5, P5 à S3) Repérer des images stéréotypées du corps véhiculées par la société (médias, réseaux sociaux). (SF, GSS5, P5 à S3)', 'Référentiel d''Éducation physique et à la santé (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Edu-physique-EPS.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
