insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P1-70-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C70'), 'primaire', array['P1']::text[], 'Français', 'attendu', '- des connaissances personnelles mobilisées ; - l’intention de l’auteur ; - les relations entre les éléments (liens logiques, texte-illustrations). - l’explicite et certains éléments implicites ; - une émotion ressentie ; - l’intention de l’auteur ; - les relations entre les éléments (liens logiques, texte-illustrations).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P1-71-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C71'), 'primaire', array['P1']::text[], 'Français', 'attendu', '- l’explicite et certains éléments implicites ; - une émotion ressentie ; - l’intention de l’auteur ; - les relations entre les éléments (chronologie, liens logiques, texte-illustrations). - l’explicite et certains éléments implicites ; - une émotion ressentie ; - l’intention de l’auteur ; - les relations entre les éléments (chronologie, texte-illustrations) ; - les éléments réels et imaginaires.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
