insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P3-72-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C72'), 'primaire', array['P3']::text[], 'Français', 'attendu', 'En répondant à des questions posées oralement, expliciter les stratégies de compréhension mobilisées : - prélever des informations explicites ; - élaborer une inférence ; - faire des hypothèses ; - relier le texte et les illustrations ; - percevoir le sens global ; - ( se) construire une représentation mentale du texte.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
