insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-20-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C20'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'Nommer et décrire les stratégies/habiletés de compréhension : - se créer des images ((se) construire une représentation mentale du texte) ; - faire des hypothèses (anticipation et interprétation) et les vérifier ; - résumer (percevoir le sens global) ; - retrouver des informations (prélever des informations explicites) ; - lire entre les lignes (élaborer des inférences) ; - relier le texte et les illustrations (mettre en relation le texte et les illustrations).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
