insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-140-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C140'), 'primaire', array['P4']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - la représentation mentale du contenu du message ; - l’intention de l’auteur ; - les caractéristiques du message entendu pour en identifier le genre ; - les relations entre les éléments (chronologies, texte-illustrations éventuelles, organisateurs textuels, reprise de l’information*) ; - le sens du texte grâce à la prise en compte des indices grammaticaux, verbaux et du fonctionnement de la langue ; - les éléments réels/imaginaires, vraisemblables/invraisemblables ; - les liens entre les actions et les motivations des personnages ; - une émotion ressentie, l’empathie éprouvée pour un personnage (traits de caractère, valeurs, comportements) ; - les informations essentielles, le sens global du message ; - les procédés langagiers et artistiques utilisés par les autrices et auteurs pour construire le ou les sens de l’œuvre.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
