insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-69-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C69'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'En répondant à des questions ou en produisant un dessin, quelques phrases ou une action qui donne à voir certains des éléments suivants :', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-94-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C94'), 'primaire', array['P4']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - les connaissances personnelles mobilisées/modifiées ; - la représentation mentale du contenu d’un document ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (texte-illustrations) ; - les mots appartenant à un même champ lexical ; - le sens du texte grâce à l’observation des indices grammaticaux et au fonctionnement de la langue ; - la distinction entre un fait et une opinion ; - son évaluation de la qualité de l’information et de la présentation visuelle d’un document.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-68-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C68'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'Attendus LIRE', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-141-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C141'), 'primaire', array['P4']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - une émotion ressentie ; - la représentation mentale du contenu d’un document ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (liens logiques) ; - le sens du texte grâce à l’observation des indices grammaticaux, verbaux et au fonctionnement de la langue ; - son adhésion à des valeurs transmises par les autrices et auteurs d’un document ; - la distinction entre un fait et une opinion. - les liens établis entre l’implicite et l’explicite ; - les liens entre les actions et les motivations des personnages ; - une émotion ressentie, l’empathie éprouvée pour un personnage (traits de caractère, valeurs, comportements) ; - la représentation mentale du contenu d’un document ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (chronologie, texte-illustrations) ; - les mots appartenant à un même champ lexical ; - le sens du texte grâce à l’observation des indices grammaticaux, verbaux et au fonctionnement de la langue ; - les éléments réels/imaginaires, vraisemblables/invraisemblables ; - les procédés langagiers et artistiques utilisés par les autrices et auteurs pour construire le ou les sens de l’œuvre ; - son jugement de gout pour un genre, un thème, des autrices et auteurs et le motiver par ses connaissances culturelles, par les procédés artistiques (image, techniques narratives, choix du narrateur…) utilisés par les autrices et auteurs ; - son adhésion ou son refus d’adhésion à des valeurs transmises par les auteurs d’un document.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-142-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C142'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'En imaginant une suite cohérente à un récit en tenant compte des informations livrées dans la ou les premières parties de celui-ci. - les liens établis entre l’implicite et l’explicite ; - une émotion ressentie ; - la représentation mentale du contenu d’un document ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (chronologiques, logiques) ; - les mots appartenant à un même champ lexical ; - le sens du texte grâce à l’observation des indices grammaticaux, verbaux et au fonctionnement de la langue ; - son adhésion à des valeurs transmises par les auteurs d’un document ; - son évaluation de la qualité de la présentation visuelle d’un document.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-142-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C142'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'En exécutant un enchainement de trois consignes écrites', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-142-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C142'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'Expliciter sa compréhension', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-72-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C72'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'En répondant à des questions posées oralement, expliciter les stratégies de compréhension mobilisées : - prélever des informations explicites ; - élaborer une inférence ; - faire des hypothèses ; - relier le texte et les illustrations ; - reformuler le sens global ; - (se) construire une représentation mentale du texte.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
