insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-74-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C74'), 'primaire', array['P4']::text[], 'Français', 'attendu', 'Rédiger un écrit qui combine plusieurs des éléments suivants en mobilisant des ressources (référentiels) :', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P4-75-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C75'), 'primaire', array['P4']::text[], 'Français', 'attendu', '- en restant dans le sujet ; - en tenant compte de l’intention et du destinataire ; - en l’organisant selon une structure textuelle simple donnée ; - en utilisant les principaux traits de ponctuation ; - en orthographiant correctement les mots connus et en appliquant les règles d’orthographe grammaticale ; - en utilisant les connecteurs* logiques, chronologiques, spatiaux, de cause/explication, d’addition ; - en utilisant les substituts lexicaux ; - en utilisant les modes et les temps appropriés pour assurer la cohérence temporelle* ; - en recourant aux lexiques courant et spécifique à une thématique ou un champ disciplinaire.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
