insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-54-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C54'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'S’adapter au contexte d’écoute par : - des conduites sociales adéquates (attente, silence, gestes, sons) ; - une écoute attentive ; - un comportement non verbal approprié selon la modalité retenue (audio/vidéo, public/privé…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
