insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-63-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C63'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'Corriger une production de son choix à l’aide d’une grille de vérification et des référentiels (dictionnaire -en ligne-, correcteur orthographique, conjugueur…) de la classe en vue de la partager.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
