insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-72-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C72'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'Écouter dans une situation d’échanges', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-67-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C67'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'Lors d’un échange en groupe : - témoigner de son écoute ; - adopter une posture d’écoute attentive ; - respecter les tours et les temps de parole.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-68-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C68'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'Attendus LIRE', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-69-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C69'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'En répondant à des questions ou en produisant un dessin, quelques phrases ou une action qui donne à voir certains des éléments', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-94-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C94'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'suivants : - les liens établis entre l’implicite et l’explicite ; - les connaissances personnelles mobilisées/modifiées ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (texte-illustrations, les liens logiques) ; - les mots appartenant à un même champ lexical ; - le sens du texte grâce à l’observation des indices grammaticaux, verbaux et au fonctionnement de la langue ; - la distinction entre un fait et une opinion ; - son évaluation de la qualité de l’information et de la présentation visuelle d’un document.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-121-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C121'), 'primaire', array['P5']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - une émotion ressentie ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (logiques) ; - le sens du texte grâce à l’observation des indices grammaticaux, verbaux et au fonctionnement de la langue ; - son adhésion à des valeurs transmises par les autrices et auteurs d’un document ; - la distinction entre un fait et une opinion.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-119-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C119'), 'primaire', array['P5']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - une émotion ressentie ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (chronologie, logiques) ; - les mots appartenant à un même champ lexical ; - le sens du texte grâce à l’observation des indices grammaticaux, verbaux et au fonctionnement de la langue ; - son adhésion à des valeurs transmises par les autrices et auteurs d’un document ; - son évaluation de la qualité de la présentation visuelle d’un document.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-119-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C119'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'En exécutant un enchainement de trois consignes écrites.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-68-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C68'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'Attendus LIRE', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-140-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C140'), 'primaire', array['P5']::text[], 'Français', 'attendu', '- les liens établis entre l’implicite et l’explicite ; - les liens entre les actions et les motivations des personnages ; - une émotion ressentie, l’empathie éprouvée pour un personnage (traits de caractère, valeurs, comportements) ; - l’intention de l’auteur ; - les caractéristiques de sa structure textuelle permettant d’identifier son genre ; - les relations entre les éléments (chronologie, texte-illustrations) ; - les mots appartenant à un même champ lexical ; - le sens du texte grâce à l’observation des indices grammaticaux, verbaux et au fonctionnement de la langue ; - les éléments réels/imaginaires, vraisemblables/invraisemblables ; - les procédés langagiers et artistiques utilisés par les autrices et auteurs pour construire le ou les sens de l’œuvre ; - son jugement de gout pour un genre, un thème, des autrices et auteurs et le motiver par ses connaissances culturelles (auteur, sujet, genre du texte), par les procédés artistiques (image, texte) utilisés par les autrices et auteurs ; - les liens artistiques, culturels entre plusieurs œuvres et mises en réseau ; - son adhésion ou son refus d’adhésion à des valeurs transmises par les autrices et auteurs d’un document.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-140-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C140'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'En imaginant une suite cohérente à un récit en tenant compte des informations livrées dans la ou les premières parties de celui-ci.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-140-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C140'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'Expliciter sa compréhension', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P5-72-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C72'), 'primaire', array['P5']::text[], 'Français', 'attendu', 'En répondant à des questions posées oralement, expliciter les stratégies de compréhension mobilisées : - prélever des informations explicites ; - élaborer une inférence ; - faire des hypothèses ; - relier le texte et les illustrations ; - reformuler le sens global ; - ( se) construire une représentation mentale du texte.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
