insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-152-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C152'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Vérifier, selon la réaction du ou des récepteurs, si l’intention de communication a été atteinte.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-152-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C152'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Ajuster son propos quand on perd l’attention de son interlocuteur.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-152-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C152'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Relever des éléments moins réussis de sa communication : - en cernant ce qui n’a pas été bien saisi ; - en reformulant les propos énoncés (précisions, ajouts...) ; - en commentant les blocages survenus et en réfléchissant à des facilitateurs de communication.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-61-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C61'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Évaluer la qualité de son écoute et de ses interventions.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-P6-62-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C62'), 'primaire', array['P6']::text[], 'Français', 'attendu', 'Relire sa production et vérifier : - le contenu des idées ; - leur organisation dans des phrases respectant une structure dominante choisie (à l’aide d’une grille de révision) ; - le respect de l’intention poursuivie ; - la précision du vocabulaire.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
