insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-196-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C196'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Expliciter le sens d’un mot : - dans son contexte ou en se référant à son cotexte*, à sa famille, à son étymologie, à sa forme… - en consultant un ouvrage de référence, un référentiel, y compris numérique.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
