insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-197-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C197'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Utiliser/prendre en compte une syntaxe adéquate à la prestation : - répétition ; - élision ; - liaisons obligatoires ; - connexions ; - système de temps...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-198-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C198'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Traiter dans le texte les indices grammaticaux qui contribuent à produire le sens : marques nominales et verbales (terminaisons) ; - marques de types et de formes de phrases ; - indices spatiotemporels ; - liens logiques et sémantiques entre les informations essentielles ; - référent des principales anaphores…', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-198-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C198'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Utiliser des indices grammaticaux qui contribuent à produire le sens : - des expansions du nom ; - des indices temporels (temps verbaux, adverbes…) ; - conjuguer correctement les verbes aux modes (indicatif et impératif) et temps adéquats.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-199-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C199'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Reconnaitre les constituants d’une phrase* : - complexe : la proposition principale et la proposition subordonnée circonstancielle de comparaison, de cause et de conséquence, de temps. - multiple : deux phrases simples coordonnées ou juxtaposées.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-199-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C199'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Relier deux phrases simples pour construire une phrase complexe en utilisant les différents procédés.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
