insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S1-207-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C207'), 'primaire', array['S1']::text[], 'Français', 'attendu', 'Évaluer et, si nécessaire, améliorer : - la lisibilité graphique ; - la pertinence : • au genre ; • à l’intention ; • à la thématique ; • aux consignes éventuelles. - l’intelligibilité : connexions, anaphores, organisateurs textuels… - la recevabilité linguistique (syntaxe, ponctuation, orthographe grammaticale et lexicale, conjugaison) en : • vérifiant les accords et chaines d’accords ; • vérifiant les homophones les plus courants ; • ayant recours à des documents de référence (papier ou numérique…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
