insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S2-176-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C176'), 'primaire', array['S2']::text[], 'Français', 'attendu', 'Reconnaitre : - les termes spécifiques d’une thématique ou d’un objet ; - les termes mélioratifs/péjoratifs ; - le sens propre, le sens figuré ; - des expressions idiomatiques ou figées ; - les sens multiples d’un mot (polysémie) ; - les préfixes et leur impact sur le sens du mot : in-, ex-, pré-, post-, co-, inter-, hyper-, super-, sub-/sous-, anti-, pro-, auto-, homo-, hétéro-...', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
