insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-238-10', (select id from public.curriculum_item where version = '2022' and code = 'FR-C238'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Élaborer et présenter une procédure en vue de réaliser une tâche scolaire (un protocole d’expérience scientifique, un tutoriel, une démarche…).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-238-11', (select id from public.curriculum_item where version = '2022' and code = 'FR-C238'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Relater oralement ou par écrit une rencontre avec une œuvre culturelle (littéraire ou non).', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-238-12', (select id from public.curriculum_item where version = '2022' and code = 'FR-C238'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Prendre position et étayer son opinion (relative à un fait d’actualité, à un choix, à une expérience…) oralement et/ou par écrit en développant et illustrant trois arguments.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
