insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-239-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C239'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Construire sa prise de parole spontanée ou préparée Évoquer ce que l’on connait du sujet. Oser proposer des idées nouvelles. Développer les idées émises. Oser s’exprimer en dépit des maladresses syntaxiques, des répétitions et des hésitations dans les formulations.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-239-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C239'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Proposer diverses formulations.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-239-3', (select id from public.curriculum_item where version = '2022' and code = 'FR-C239'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Accepter d’utiliser provisoirement un vocabulaire approximatif ou le même mot pour exprimer diverses choses. (SF, P1 à P6)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-240-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C240'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'tière de filières d’études et de métiers ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignées à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-5', (select id from public.curriculum_item where version = '2022' and code = 'FR-C221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples d’opportunités offertes par le référentiel', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-241-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C241'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'De nombreux contenus du référentiel constituent des occasions de découvrir une diversité de métiers : - dans le domaine du livre : écrivain, illustrateur, infographiste, relieur, éditeur… ; - dans le domaine de l’audiovisuel et des arts vivants : acteur, metteur en scène, technicien (son, lumière…), décorateur… ; - dans le domaine du numérique : infographiste, web designer, influenceur…', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-242-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C242'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Par ailleurs, la discipline « français » est le lieu privilégié de prise d’informations et de recherches documentaires, pouvant porter sur les métiers et les professions. De plus, certains genres abordés en classe se prêtent particulièrement à la', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-242-2', (select id from public.curriculum_item where version = '2022' and code = 'FR-C242'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'découverte de différentes sphères professionnelles :', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-243-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C243'), 'primaire', array['S3']::text[], 'Français', 'attendu', '- article, documentaire, catalogue, dépliant, description, récit d’expérience… ; - débat, table ronde, interview, demande d’explication dans une relation asymétrique, invitation… Les apprentissages et découvertes des élèves constitueront des opportunités pour', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-244-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C244'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'mettre en relation des métiers ou des sphères professionnelles avec les options et filières d’études de l’après tronc commun, et/ou avec des parcours d’études ou de formations et/ou avec des projets personnels.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-245-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C245'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'a appris du monde scolaire, de la diversité des filières et options scolaires qui s’ouvrent après le tronc commun et ce qu’il connait du monde des activités', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-246-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C246'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'professionnelles, de manière à se forger une vision de l’avenir et à se mettre en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, gouts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à « construire leur vie ». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-221-6', (select id from public.curriculum_item where version = '2022' and code = 'FR-C221'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exemples d’opportunités offertes par le référentiel', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-247-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C247'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Le travail d’acculturation* à l’écrit familiarise les élèves avec la culture écrite, ses œuvres, ses codes linguistiques et ses pratiques sociales. L’entrée dans la langue écrite démultiplie les possibilités de compréhension et d’action sur le monde et permet aux élèves de se construire une identité de lecteur et de scripteur.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-248-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C248'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Tout au long de son parcours, l’élève est amené à apprécier des documents ou des œuvres, y réagir et agir. Ce processus d’appréciation est un processus de lecture consistant à formuler un jugement sur le texte. Ce jugement peut être plus ou moins motivé, c’est-à-dire fondé sur des arguments qui peuvent être émotionnels et/ou rationnels. Ceux-ci peuvent être d’ordres cognitif (basés sur la lisibilité perçue),', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-249-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C249'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'éthique (basés sur les valeurs humaines), référentiel (basés sur le type d’univers concerné) ou esthétique (basés sur les qualités formelles). En contexte scolaire, l’appréciation s’appuie sur la compréhension et l’interprétation, et elle consiste à favoriser l’expression d’un jugement de gout motivé, base de tout choix.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-250-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C250'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Le référentiel favorise également le contact avec la littérature patrimoniale et la rencontre avec des autrices et auteurs inspirants. En enrichissant leur bagage littéraire, les élèves se construisent une « bibliothèque intérieure », identifient les thématiques qui leur plaisent le mieux et apprennent à rencontrer et à apprécier de nouvelles thématiques, de manière à élargir leur horizon. Ce bagage contribue à', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-251-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C251'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'concevoir et à se projeter dans un avenir désirable.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-252-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C252'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Le processus de révision est une composante importante de la production d’écrits qui consiste à relire tout ou une partie du texte, et à examiner attentivement si les objectifs d’écriture de départ sont atteints. Elle repose sur une forme d’évaluation, qui peut être effectuée par le scripteur lui-même ou être menée par des enseignants et/ou d’autres élèves. Lors de la phase de révision, l’élève s’appuie souvent sur ces feedbacks pour opérer des changements de contenu, il apporte des modifications pour clarifier ou développer le sens du texte. Ces changements peuvent inclure la réorganisation des idées, l’ajout ou la suppression de parties entières du texte, l’ajustement du choix des mots et des structures de phrases…', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-253-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C253'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'La structure argumentative est l’une des cinq structures travaillées tout au long du parcours, tant en production qu’en réception, à travers de nombreux genres (courrier de demande, affiche de sensibilisation, critique de livres ou de films, dialogue argumentatif, billet d’humeur…). L’argumentation s’enrichit par la pratique de la lecture distanciée qui repose sur la maitrise de savoir-faire tels qu’associer des valeurs à un personnage, évaluer ou donner son avis tant sur le message véhiculé par un document que sur les procédés utilisés par les autrices et auteurs. Sa maitrise conditionne le développement d’un jugement argumenté et plus largement d’une pensée critique indispensable à tous les élèves du tronc commun pour devenir des citoyens actifs et responsables.', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-254-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C254'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Identifier des genres théâtraux (marionnette, théâtre d’ombre statique/mobile, clown…). (S) Imiter différents timbres de voix humaines en chantant ou en parlant. (SF)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-255-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C255'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Décrire hauteur, durée et intensité du son. (S)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-256-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C256'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Lors des expériences culturelles et artistiques,', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-257-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C257'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'exprimer ce qu''on a vu, imaginé, ressenti. (S) Débattre collectivement. (SF)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('FR-S3-258-1', (select id from public.curriculum_item where version = '2022' and code = 'FR-C258'), 'primaire', array['S3']::text[], 'Français', 'attendu', 'Exprimer son accord et son désaccord de manière collective. (SF)', 'Référentiel de Français et de Langues anciennes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Francais-FRALA.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
