insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-1-1', (select id from public.curriculum_item where version = '2022' and code = 'HG-C1'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Nommer les durées et leurs découpages figurés sur une représentation du temps.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-1-2', (select id from public.curriculum_item where version = '2022' and code = 'HG-C1'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Énoncer le nom d’un jour de la semaine, d’une saison en établissant une relation de succession (avant/après).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-1-3', (select id from public.curriculum_item where version = '2022' and code = 'HG-C1'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Identifier le début ou la fin d’une durée, d’un cycle et de chacun de ses découpages internes.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-1-4', (select id from public.curriculum_item where version = '2022' and code = 'HG-C1'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Décrire des durées et leurs découpages en s’appuyant, selon les cas, sur la longueur du jour, l’observation de la nature et du climat à l’échelle locale (environnement immédiat des élèves), l’activité exercée par l’enfant et/ou ses proches.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
