insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-2-1', (select id from public.curriculum_item where version = '2022' and code = 'HG-C2'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Utiliser le vocabulaire et les notions liés à l’appréhension du temps pour décrire la dimension temporelle (chronologie, ancienneté, durée, fréquence) de faits vécus par soi ou par des personnes proches.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
