insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-3-3', (select id from public.curriculum_item where version = '2022' and code = 'HG-C3'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Compléter une représentation du temps avec quatre activités du quotidien ou quatre faits vécus par soi.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
