insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-3-5', (select id from public.curriculum_item where version = '2022' and code = 'HG-C3'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Comparer la durée de deux activités en utilisant les termes « plus longue que »/« plus courte que ».', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-4-1', (select id from public.curriculum_item where version = '2022' and code = 'HG-C4'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Interroger une personne proche pour caractériser des activités du quotidien autrefois : pour jouer, apprendre, communiquer, se déplacer.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-5-1', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Reconnaitre un objet ou une image comme étant une trace d’une activité vécue dans le passé par soi.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-5-2', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Associer une trace du passé à une des activités de son quotidien : pour jouer, apprendre, communiquer, se déplacer.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-5-3', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Identifier soit deux différences, soit deux similitudes, soit une différence et une similitude entre un objet courant actuel et un objet ancien de même fonction.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-5-4', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Compléter une représentation du temps d’une semaine, graduée en jours, à l’aide d’images d’activités vécues par l’enfant et la lire oralement, afin de mettre en évidence leur chronologie ou leur ancienneté.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P1-5-5', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P1']::text[], 'Formation historique et géographique', 'attendu', 'Sélectionner, parmi quatre propositions, une trace du passé en lien avec une activité du quotidien ou un évènement de la vie de l’enfant.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
