insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P4-5-5', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P4']::text[], 'Formation historique et géographique', 'attendu', 'Compléter une frise chronologique graduée en siècles du Ier siècle av. J.-C. à aujourd’hui par des traces ou des informations relatives à la thématique de l’année et l’annoter en mobilisant des repères temporels significatifs.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
