insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P4-5-7', (select id from public.curriculum_item where version = '2022' and code = 'HG-C5'), 'primaire', array['P4']::text[], 'Formation historique et géographique', 'attendu', 'Sur la base de deux documents traitant de l’accès aux savoirs et à l’instruction, construire un tableau à simple entrée pour comparer une réalité de vie de l’élève avec celle vécue par un autre, durant un des moments clés étudiés et identifier des éléments qui changent et des éléments qui ne changent pas, en mobilisant des repères temporels significatifs et un vocabulaire temporel spécifique.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
