insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P2-13-8', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P2']::text[], 'Formation historique et géographique', 'attendu', 'Identifier des rôles d’acteurs (avec une attention au genre) qui composent des organisations de l’environnement local.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
