insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P2-13-10', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P2']::text[], 'Formation historique et géographique', 'attendu', 'Au départ d’une visite de terrain dans le quartier/la localité de l’école ou d’une visite virtuelle (ex. : à partir de photographies…), identifier des lieux qui proposent des biens ou des services.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P2-13-11', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P2']::text[], 'Formation historique et géographique', 'attendu', 'Au départ d’une visite de terrain dans le quartier/la localité de l’école ou d’une visite virtuelle/rencontre, dresser une liste structurée des personnes rencontrées et leurs rôles et comparer la répartition du travail entre femmes et hommes.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P2-13-12', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P2']::text[], 'Formation historique et géographique', 'attendu', 'Associer une combinaison de pièces (1 €, 2 €) et/ou billets (5 €, 10 €, 20 €, 50 €, 100 €) avec le prix d’un bien ou d’un service donné (inférieur ou égal à 100 €).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-P2-13-13', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['P2']::text[], 'Formation historique et géographique', 'attendu', 'Formuler oralement des questions qui pourraient être posées à une personne (ou à des personnes) qui exerce(nt) une activité, dans le quartier ou la localité de l’école, afin d’en savoir plus sur cette activité : que fait-elle concrètement ? Comment se passe une journée habituelle de travail ?… Communiquer les observations d’une partie de la visite de terrain/virtuelle, en s’aidant des traces conservées.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
