insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-10', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Établir le lien entre égalité et équité.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-11', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Identifier dans un cas précis laquelle des trois normes (égalité, mérite et besoin) inspire la façon de distribuer certains biens entre des individus et/ou des groupes sociaux.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-12', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemplifier l’incidence de revendications et de luttes sociales dans l’évolution des rapports de genre.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-13', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Collecter des données qui illustrent le décalage entre le principe de l’égalité entre femmes et hommes et la situation effective dans le monde du travail.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-14', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Au départ d’une analyse de données statistiques (par exemple, résultats des enquêtes budget-temps), mettre en évidence des inégalités de genre dans la contribution des femmes et des hommes à une sphère du monde du travail (par exemple, les activités domestiques et ménagères, les soins aux personnes…).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-15', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Sur la base de documents, questionner le modèle de la sécurité sociale belge aujourd’hui (par exemple, pérennité, adéquation à la société actuelle, égalité, équité…).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-16', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Identifier une situation de répartition inégalitaire (économique, entre genres…) et formuler des propositions argumentées permettant d’atténuer cette inégalité.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-17', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Sur la base du circuit économique élaboré au cours des différentes années, formuler un avis argumenté sur la place et le rôle de l’État dans la sphère économique.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-18', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de contenus ou d’attendus contributifs Mobiliser des repères de temps et des représentations du temps pour se situer soi-même, pour situer des faits dans le temps et mettre en évidence une chronologie, des changements, des continuités. (FH, C, P1-S3) Utiliser des repères spatiaux et/ou des représentations de l’espace pour (se) situer/se déplacer/(s’)orienter. (FG, C, P1-S3) Exemplifier le fait d’être à la fois un individu singulier (par exemple au niveau physique et du caractère) et membre de différents groupes (groupe-classe, membre d’une famille, etc.). (FES, S, P1) Recueillir des informations. (FH, SF, P1-P3) Les élèves caractérisent, illustrent, questionnent la notion de besoin et progressivement, ils la différencient de la notion d’envie. (FES, P1-P3) Ils formulent des questions, interrogent des personnes-ressources. (FES, P2) Exemplifier la différence entre un besoin et une envie. (FES, S, P3) Annoter/construire une représentation de l’espace. (FG, SF, P1-S3)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-19', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de contenus ou d’attendus contributifs Luttes menées par les acteurs de changement et facteurs de changement. (FH, S, P4-S3) Expliquer en quoi le IIIe Reich n’est pas un régime démocratique. (FH, S, S3) Établir des liens entre des composantes spatiales pour expliquer des localisations, des répartitions/dynamiques spatiales. (FG, C, P2-S3) Les élèves abordent différents éléments guidant les choix et le comportement : règles, genre, identité, culture, publicité, déterminants de la consommation… (FES, P1-S1). Ils alimentent leurs opinions (ex. : formuler un avis argumenté sur des impacts économiques et sociaux du développement de la consommation collaborative et de l’e-commerce. (FES, C, S1) Lois décrétant l’instruction primaire gratuite et obligatoire jusqu’à 14 ans et la suppression du travail des enfants de moins de 14 ans (d’application à la fin de la Première Guerre mondiale). (FH, S, P4) Constitution belge. (FH, S, S1) Sécurité sociale, suffrage universel, libertés fondamentales, séparation des pouvoirs, Déclaration universelle des droits de l’homme. (FH, S, S3) Justice sociale : identifier dans un cas précis laquelle des trois normes (égalité, mérite et besoin) inspire la façon de distribuer certains biens entre des individus et/ou des groupes sociaux. (FES, S, S3) Exemplifier différentes manières de communiquer avec ses camarades de classe, avec son instituteur/institutrice, avec la direction. (FES, S, P1) Identifier des règles qui peuvent soutenir la vie en collectivité en observant des ressemblances/différences de comportements acceptés ou pas, au sein de l’école et dans l’environnement proche. (FES, S, P2) Identifier des règles qui encadrent/limitent des pratiques virtuelles. (FES, S, S1) Les élèves abordent les apports culturels des vagues de migration en Belgique de 1945 à nos jours (FH, S, P6), et les discriminations, persécutions, déportations et génocides durant le régime du IIIe Reich. (FH, S, S3) Exemplifier des apports de la migration, ainsi que des leviers et des freins à l’intégration des migrants au départ d’un processus de collecte de données. (FES, C, S2) Identifier des modes de présentation de soi et de relation aux autres dans l’espace numérique et leurs effets sur soi et sur les autres. (FES, SF, S1) Aborder des facteurs de changement au travers d’acteurs, d’actrices. (FH, S, P4-S3) Mixité scolaire. (FH, S, P4) Mouvements féministes, droit de vote des femmes. (FH, S, S3) Exemplifier des façons de vivre (gouts, rôles, langage…) qui sont transmises entre générations, avec une attention particulière aux rôles masculins et féminins. (FES, S, P4) Au départ d’une analyse de données statistiques (par exemple, résultats des enquêtes budget-temps), mettre en évidence des inégalités de genre dans la contribution des femmes et des hommes à une sphère du monde du travail (ex. : les activités domestiques et ménagères, les soins aux personnes…). (FES, SF, S3) Exemple d’acteur/actrice du mouvement ouvrier, 1er mai. (FH, S, P5) Mouvement ouvrier, syndicats, mouvements féministes, mouvements flamand et wallon, mouvements et partis indépendantistes congolais. (FH, S, S3) Exemplifier l’incidence de revendications et de luttes sociales dans l’évolution des rapports de genre. (FES, S, S3)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-20', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de contenus ou d’attendus contributifs Identifier une situation de répartition inégalitaire et formuler des propositions argumentées permettant d’atténuer cette inégalité. (FES, C, S3) Sur la base de documents, questionner le modèle de la sécurité sociale belge aujourd’hui (ex. : pérennité, adéquation à la société actuelle, égalité, équité…). (FES, C, S3) Les repères temporels et les savoirs culturels permettent aux élèves de se référer à leur passé. (FH, S, P1-S3) Ils les mobilisent pour se situer, situer des faits dans le temps. Les réalités d’aujourd’hui sont inscrites dans une perspective historique pour mettre en évidence des continuités, des changements et des étapes d’une évolution entre hier et aujourd’hui. (FH, C, P1-S3) Quelques processus qui marquent l’évolution de l’occupation des espaces. (FG, S, S1) Décrire un exemple d’évolution de l’occupation du sol qui illustre un effet positif ou négatif de l’évolution des espaces sur l’environnement. (FG, S, S1) Sur la base de documents, questionner le modèle de la sécurité sociale belge aujourd’hui (ex. : pérennité, adéquation à la société actuelle, égalité, équité…). (FES, C, S3) Les élèves envisagent les réalités d’aujourd’hui. (FH, S, P4-S3) Utiliser des repères spatiaux et/ou des représentations de l’espace pour (se) situer/se déplacer/(s’)orienter. (FG, C, P1-S3) Tout au long du tronc commun, l’élève apprend à se situer dans son environnement économique et social, dans la réalité qui l’entoure, via notamment la compétence « éclairer des faits économiques et sociaux en mobilisant des Utiliser un(e) minuteur (timer), sablier, montre analogique et digitale, horloge (FH, SF, P1-P2).', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-21', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Utiliser un arbre généalogique simple (quatre générations). (FH, SF, P3) Mobiliser des repères de temps et des représentations du temps pour se situer soi-même, pour situer des faits dans le temps et mettre en évidence une chronologie, des changements, des continuités. (FH, C, P1-S3) Justifier l’importance de la vulnérabilité d’une population en faisant référence à son effectif, son niveau de développement socioéconomique et à la manière d’occuper l’espace. (FG, C, S3) Justifier la localisation d’un aménagement en faisant référence à un aléa. (FG, C, S3) Sur la base de revenus et de dépenses, élaborer un budget et calculer le solde positif et/ou négatif. (FES, SF, P6) Citer des envies suscitées par des médias ou par les pairs. (FES, S, P3) Exemplifier la différence entre un besoin et une envie. (FES, S, P3) Formuler une explication possible au fait qu’une publicité peut entrainer ou non un changement de comportement. (FES, SF, P3)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-22', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de contenus ou d’attendus contributifs Présence de langues d’origine européenne dans le monde ; anglais, une langue globale. (FH, S, S2) Acteurs de changement. (FH, S, P4-S3) Révolution belge/Indépendance de la Belgique, Construction européenne. (FH, S, P5-S3) Repères spatiaux, vocabulaire, notions et modèles pour se situer, se déplacer, situer, localiser un lieu, un fait. (FG, S, P1-S3) communautés, la frontière linguistique et les provinces. (FG, S, P5) Les élèves distinguent les groupes familiaux d’autres groupes sociaux (FES, P1), identifient des groupes de pairs et envisagent les influences de ceux-ci sur les choix d’un individu. (FES, P4) Nommer et dater les quatre moments de rupture qui ont marqué l’évolution de la multiculturalité dans nos régions. (FH, S, P6) Identifier des apports culturels des vagues de migration en Belgique de 1945 à nos jours. (FH, S, P6) Citer et exemplifier les principales causes de la migration. (FES, S, S2) Identifier des représentations associées à la migration et des évolutions de ces représentations. (FES, S, S2) Expliquer en quoi les réseaux sociaux peuvent contribuer à la fois au renforcement des liens sociaux et à l’exclusion sociale. (FES, SF, S1)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-13-23', (select id from public.curriculum_item where version = '2022' and code = 'HG-C13'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de contenus ou d’attendus contributifs Distinguer une trace du passé d’un travail postérieur. (FH, SF, P4) Associer une trace du passé à une des activités de son quotidien : pour jouer, apprendre, communiquer, se déplacer. (FH, SF, P1-P2) Caractériser un paysage/environnement pour contextualiser un fait/phénomène. (FG, C, P1-S3) Budget : classer toutes les pièces de monnaie et tous les billets par ordre de grandeur (valeur faciale). (FES, S, P1-P3) Statut et rôles : identifier des rôles d’acteurs (avec une attention au genre) qui composent des organisations de l’environnement local. (FES, S, P2) Exemplifier des biens individuels et des biens collectifs dans le cadre scolaire.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-1', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Identifier parmi des faits, évènements, phénomènes historiques ceux qui relèvent de la démocratie, ceux qui relèvent de l’absolutisme, ceux qui relèvent du totalitarisme, ceux qui témoignent d’une démocratisation. (FH, S, S3) Comparer oralement une même activité du quotidien vécue par l’enfant ou un proche aujourd’hui et une activité de même nature dans le passé, pour mettre en évidence des éléments qui changent et des éléments qui ne changent pas, en mobilisant des repères temporels. (FH, C, P1-P2) Lire un paysage, lire un croquis cartographique, un plan, une carte. (FG, SF, P1-S3) Établir des liens entre des composantes spatiales pour expliquer des localisations, des répartitions/dynamiques spatiales. (FG, S, P2-S3) En comparant les informations recueillies dans différents supports, repérer des ressemblances et des différences entre des contenus de la transmission intergénérationnelle. (FES, SF, P4) En comparant des impacts économiques, sociaux environnementaux de différents modes de production et de consommation, justifier l’appartenance d’acteurs au commerce équitable. (FES, SF, P6)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-2', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de contenus ou d’attendus contributifs La formation historique poursuit l’objectif de développer l’apprentissage d’un vocabulaire exprimant ces notions grâce à l’installation de repères temporels (FH, S, P1-P4) et d’un vocabulaire et notions pour appréhender le temps. (FH, S, P1-P5) Inscrire dans une perspective historique une réalité d’aujourd’hui… (FH, C, P1-S3) Les impacts économiques et sociaux des délocalisations sur la société (par exemple du point de vue des producteurs, des travailleurs, des consommateurs, de l’État). (FES, S2) Les liens entre l’offre et la demande, et les prix d’équilibre. (FES, S, S1) Citer et exemplifier des causes de la migration (ex. : causes d’ordre économique, politique, environnemental ou culturel). (FES, S, S2) Utiliser une représentation du temps/un outil de mesure du temps. (FH, SF, P1-S3) Mobiliser des repères de temps et des représentations du temps pour se situer soi-même, pour situer des faits dans le temps et mettre en évidence une chronologie, des changements, des continuités. (FH, C, P1-S3) Annoter/construire une représentation de l’espace. (FG, SF, P1-S3) Construire un circuit économique national global qui intègre différents acteurs et flux (internes et externes). (FES, C, S2) Structurer collectivement les informations collectées concernant l’organisation visitée. (FES, C, P1) Utiliser méthodiquement (…) un moteur de recherche, un portail numérique. (FH, SF, P5) Les représentations de l’espace étant majoritairement numériques (vue verticale, globe virtuel, géoportail…), ces outils sont mobilisés. (FG, SF, P1-S3) L’analyse des informations à l’aide d’outils variés spécifiques aux sciences économiques et sociales peut s’appuyer sur des outils numériques. (FES, SF, P1-S3)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-3', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de contenus ou d’attendus contributifs Collecter des données qui illustrent le décalage entre le principe de l’égalité entre femmes et hommes et la situation effective dans le monde du travail. (FES, SF, S3) Identifier des représentations associées à la migration et des évolutions de ces représentations. (FES, S, S2) Expliquer des raisons du développement d’un marché commun européen. (FH, S, S2) Établir des liens entre des composantes spatiales pour expliquer des localisations, des répartitions/dynamiques spatiales. (FG, C, P2-S3) Identifier des impacts économiques, sociaux et environnementaux de différents modes de production et de consommation. (FES, S, P6) Sur la base du circuit économique élaboré au cours des différentes années, formuler un avis argumenté sur la place et le rôle de l’État dans la sphère économique. (FES, C, S3) Exemplifier la notion de libre circulation des biens et des personnes dans l’espace européen, en envisageant les avantages et les inconvénients. (FES, S, S2)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-4', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de contenus ou d’attendus contributifs Mobiliser des repères de temps et des représentations du temps pour se situer soi-même, pour situer des faits dans le temps et mettre en évidence une chronologie, des changements, des continuités. (FH, C, P1-S3) Annoter/construire une représentation de l’espace. (FG, SF, P1-S3) Réaliser une publicité commerciale et formuler un avis argumenté quant à l’efficacité des procédés mis en place. (FES, C, P3) Dans le cas précis d’une organisation pratiquant l’économie sociale et solidaire ou circulaire, décrire comment les biens et services sont produits et l’incidence de ces activités dans l’environnement local (ex. : renforcement des relations entre producteurs et consommateurs, relations de proximité, valorisation d’un savoir-faire local). (FES, S, P6)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-5', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'S’orienter repose sur la connaissance de soi, mais aussi sur une découverte du monde extérieur et de l’éventail des possibles qu’il offre en matière de filières d’études et de métiers ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignés à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-6', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Les apprentissages et découvertes des élèves constitueront des opportunités pour mettre en relation des métiers ou sphères professionnelles avec les options et filières d’études de l’après tronc commun, et/ou avec des parcours d’études ou de formations et/ou avec des projets personnels.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-7', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de sphères professionnelles et métiers en lien avec les démarches disciplinaires : géographe, économiste, sociologue, historien, mais aussi archéologue, assistant social, journaliste, enseignant, archiviste, documentaliste, écrivain, manager touriste, scénariste, guide de musée, conservateur, historien de l’art, avocat, manager logistique, ingénieur en prévention et gestion de conflit, ingénieur de l’action sociale, e-business, business-data analyst, conseiller en développement durable, gestionnaire en écologie... et toutes les filières associées à ces métiers.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-8', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples de sphères professionnelles et métiers en lien avec des contenus disciplinaires : - en lien avec la mondialisation (travail dans un centre d’accueil, une ONG, secteur du transporteur, de l’import-export…) ; - en lien avec les inégalités sociales (syndicaliste, assistant social, agent dans un organisme de défense des droits de la femme…) ; - en lien avec le développement durable (horticulteur, gestionnaire ou technicien en environnement, manager en conception des aliments, sylviculteur, valoriste généraliste…) ; - en lien avec la consommation et la production (agent agricole polyvalent, artisan, commerçant, chef d’entreprise, métiers liés à l’horeca…) ; - en lien avec la communication (téléopérateur, webmaster, business-analyst, journaliste…) ; - en lien avec la multiculturalité (attaché ou animateur culturel, interprète, médiateur, agent de lutte contre le racisme…) ; - … Illustrer différentes formes de travail (rémunéré, domestique, bénévole). (FES, S, P5) Collecter des données qui illustrent le décalage entre le principe de l’égalité entre femmes et hommes et la situation effective dans le monde du travail. (FES, SF, S3) Tout au long du tronc commun, l’élève découvre progressivement des mécanismes de l’économie via l’analyse de la production, de l’agent économique « entreprises », du travail et de ses différentes formes, des facteurs de production, de la redistribution, du marché et développe un regard critique sur ces mécanismes et sur la place et le rôle de l’État dans la sphère économique et sociale. (FES)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-9', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Tout au long du tronc commun, l’élève sera amené à travailler des notions relatives à la consommation (choix de consommation, déterminants de la consommation, modes de consommation, effets de la consommation sur la société, pratiques de consommation alternatives…) afin de l’aider à devenir un citoyen responsable.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-10', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Un focus sera régulièrement mis sur la notion de budget, d’abord par l’analyse des différentes formes de monnaie, ensuite en abordant les notions telles que revenus, dépenses, missions des banques (épargnes, crédits, gestion de moyens de paiement) et enfin, en initiant les élèves à la gestion budgétaire. Cette notion relève de l’éducation financière et a pour ambition d’apporter des connaissances, mais aussi un esprit critique, et d’aider ainsi chaque jeune à parcourir son « chemin financier », en évitant un maximum d’embuches.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-11', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Différents enjeux globaux sont travaillés de la P5 à la S3 : multiculturalité, l’évolution des modes de production et de consommation (en lien avec les impacts environnementaux sous l’angle du développement durable), le processus de mondialisation, le processus de démocratisation. (FH) Différents enjeux globaux sont travaillés de la P6 à la S3 : réchauffement climatique, effets positifs et négatifs de l’évolution de l’occupation du sol sur l’environnement, mondialisation, vulnérabilité d’un espace face aux aléas. (FG) Différents enjeux globaux sont travaillés de la P6 à la S3 : développement durable, la consommation collaborative et l’e-commerce, la mondialisation et les migrations. (FES)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-12', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Relevant davantage d’un savoir-agir, il s’agit ici pour l’élève de rassembler, d’articuler et d’incarner ce qu’il a appris sur lui-même et sur les autres, ce qu’il a appris du monde scolaire, de la diversité des filières et options scolaires qui s’ouvrent après le tronc commun et ce qu’il connait du monde des activités professionnelles, de manière à se forger une vision de l’avenir et à se mettre en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, gouts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à « construire leur vie ». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-13', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Un questionnement récurrent en formation historique est la mise en évidence des changements et des ruptures. Il apparait qu’il y a de grands parallèles avec le développement de la capacité à prendre conscience des limites et des contraintes.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-14', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'En quelque sorte, pour agir sur sa vie, l’élève doit se préparer et répondre à un questionnement que la formation historique doit aider à élaborer.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-15', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Tout au long de la formation géographique, l’élève développe la connaissance d’effets d’activités du quotidien sur l’environnement ou des effets d’aménagements pour mettre en valeur un territoire ou faire face à des problèmes. Ces références lui permettent d’envisager (ou l’entrainent à envisager) différentes manières d’agir individuellement ou collectivement face à une situation ou un problème nouveau tout en évaluant des effets de ces/ses actions sur l’environnement proche et/ou lointain.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-16', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Pour un acte de consommation et/ou de production donné et au départ de l’idée de développement durable, formuler des questions relatives aux tensions qui peuvent exister entre des intérêts individuels et des intérêts collectifs des générations actuelles et générations futures. (FES, C, P6) Sur la base de documents, questionner le modèle de la sécurité sociale belge aujourd’hui (par exemple, pérennité, adéquation à la société actuelle, égalité, équité…). (FES, C, S3)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-17', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Poser un regard critique sur des traces du passé et des travaux postérieurs : voilà un axe essentiel de la formation historique qui contribue à l’élaboration de la visée 6. Le fait d’articuler les facteurs, de comprendre les liens de causalité en les identifiant et les décortiquant.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-18', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'De même, apprendre à inscrire dans une perspective historique une réalité d’aujourd’hui, en mettant en évidence les continuités et les changements, est une compétence historique essentielle qui permet d’étoffer et de grandir la capacité de choix d’un élève en fin de tronc commun.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-19', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Par l’analyse du travail en tant qu’activité économique et sociale, l’élève peut prendre conscience que le travail rémunéré n’est pas la seule manière de s’intégrer dans le monde économique et social. Le travail domestique et bénévole représente également une partie importante dans le monde du travail. (FES, P3 et P5) Le référentiel de formation historique privilégie la justification et l’argumentation.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-20', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Différents savoir-faire liés à la critique et l’exercice des compétences « Porter un regard critique sur des traces du passé et des travaux postérieurs » (FH, C, P1-S3) et « Inscrire dans une perspective historique une réalité d’aujourd’hui en mettant en évidence des continuités, des changements et des étapes d’une évolution entre hier et aujourd’hui » (FH, C, P1-S3) permettent d’atteindre cet objectif.', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('HG-S3-14-21', (select id from public.curriculum_item where version = '2022' and code = 'HG-C14'), 'primaire', array['S3']::text[], 'Formation historique et géographique', 'attendu', 'Établir des liens entre des composantes spatiales pour expliquer des localisations, des répartitions/dynamiques spatiales. (FG, C, P2-S3) Formuler un avis argumenté sur une question économique et sociale en s’appuyant sur les concepts abordés. (FES, C, P4-S3)', 'Référentiel de Formation historique, géographique, économique et sociale (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Hist-geo-FHGES.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
