insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-C330', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], 'Langue moderne', 'competence', 'intentions de', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-C331', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], 'Langue moderne', 'competence', 'Dynamique • l’élève participe aux échanges sans les animer • l’interlocuteur, natif ou assimilé - s’adresse - se montre - s’exprime dans une', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-C332', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], 'Langue moderne', 'competence', 'Lexique usage correct d’un répertoire • de mots de base, de mots internationalement partagés • d’énoncés très courts (généralement des expressions idiomatiques et/ou routinisées), en lien avec la sphère précitée Grammaire • utilisation de formes grammaticales simples et de structures syntaxiques mémorisées • étendue grammaticale : outre les items pour lesquels des attendus grammaticaux ont été formulés spécifiquement cette année, les productions des élèves pourraient faire appel à des notions grammaticales qui seront abordées ultérieurement, sans qu’une erreur éventuelle relative à cette notion ne pénalise l’élève', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-C333', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], 'Langue moderne', 'competence', 'Prononciation, intonation et débit • prononciation globalement compréhensible par un auditeur attentif et coopératif • intonation adéquate, au service de l’intention communicative • débit lent et nombreuses pauses pour permettre à l’élève de chercher ses mots, pour prononcer les mots moins familiers Correction sociolinguistique • utilisation correcte des formes de politesse les plus élémentaires • quelques erreurs qui peuvent nécessiter des efforts de compréhension de la part du destinataire • de nombreuses pauses pour permettre à l’élève de chercher ses mots, pour prononcer les mots', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
