insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-C339', (select id from public.curriculum_item where version = '2022' and code = 'LM-0'), 'primaire', array['S3']::text[], 'Langue moderne', 'competence', 'et de lieux • description de personnes et d’objets À visée injonctive • consignes ou instructions pour effectuer une activité (bricolage, jeu, itinéraire avec plan) A. Planifier • se forger une représentation mentale de la production attendue • envisager les informations à communiquer • sélectionner les ressources linguistiques et tirer de son répertoire une série d’expressions', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
