insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P5-11-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-C11'), 'primaire', array['P5']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui respecte l’interlocuteur.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P5-39-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C39'), 'primaire', array['P5']::text[], 'Langue moderne', 'attendu', 'Production orale très courte et simple • pour (s’)informer ; • constituée de mots isolés, d’énoncés très courts juxtaposés (généralement des expressions idiomatiques et/ou routinisées).', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P5-39-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C39'), 'primaire', array['P5']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • prend la forme : - de réponses adéquates à des questions ; - de formules de politesse et de salutations. • respecte les caractéristiques reprises dans l’annexe 3 pour le niveau et l’année visés.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P5-39-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-C39'), 'primaire', array['P5']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui respecte l’interlocuteur.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P5-40-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C40'), 'primaire', array['P5']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification de la plupart des informations pertinentes par rapport à la tâche, au travers, par exemple, d’un dessin, un schéma, une liste, un mime, des mots ou des phrases simples.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P5-14-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C14'), 'primaire', array['P5']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification de la plupart des informations pertinentes par rapport à l’action à poser.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-P5-14-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C14'), 'primaire', array['P5']::text[], 'Langue moderne', 'attendu', 'Action en exécution d’une suite limitée de consignes ou d’instructions au travers, par exemple, de mouvements, de manipulations d’objets, de gestes, de déplacements qui témoignent de la compréhension de l’injonction.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
