insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-38-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C38'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Niveau du CECRL visé en 2e secondaire : B1.1', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-59-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C59'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Production orale courte et simple : • pour informer et/ou pour faire agir ; • constituée essentiellement de structures simples et complexes.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-59-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C59'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • respecte les caractéristiques reprises dans l’annexe 3 pour le niveau et l’année visés.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-59-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-C59'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui : • respecte l’interlocuteur ; • permet une compréhension sans équivoque.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-60-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C60'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Production orale simple : • pour s’informer et informer autrui et/ou pour faire agir ; • constituée essentiellement de phrases courtes, articulées, simples et complexes.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-60-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C60'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Cette production orale : • prend la forme : - de réponses adéquates à des questions (exemples : répliques simples, compte rendu, description) ; - de questions ; - d’injonctions ; - de formules de politesse et de salutations. • respecte les caractéristiques définies dans l’annexe 3 en utilisant, au besoin, les stratégies adéquates.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-60-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-C60'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Adaptation du comportement et/ou de la formulation du message par le recours à des marqueurs sociolinguistiques, en lien avec le contexte socioculturel, afin de garantir une communication qui : • respecte l’interlocuteur ; • permet une compréhension sans équivoque.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-121-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C121'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification des informations pertinentes par rapport à la tâche, au travers, par exemple, d’un plan, un schéma à annoter, une liste, de phrases simples, d’un résumé en français comprenant les grandes lignes d’une histoire.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-93-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C93'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Production : • verbale (orale ou écrite en français) qui témoigne de l’identification des consignes, instructions ou injonctions pertinente par rapport à la tâche, au travers, par exemple, d’une liste, de phrases simples, d’un résumé en français comprenant les grandes lignes d’une procédure ; • non verbale en exécution d’une suite limitée de consignes ou d’instructions au travers, par exemple, de mouvements, de manipulations d’objets, de gestes, de déplacements qui témoignent de la compréhension de l’injonction.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-93-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C93'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Transmission, dans la langue de scolarisation, à une tierce personne, des éléments essentiels et pertinents contenus dans des instructions ou informations reçues en langue cible.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-15-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C15'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Identification d’un ou plusieurs éléments qui témoignent : • par exemple, du patrimoine, de traditions, de la création artistique, de modes de vie ou de modes de pensées et façons de voir le monde ; • de similitudes et de différences dans les marqueurs sociolinguistiques ; • de similitudes et de différences entre cultures ou d’une conception stéréotypée des autres cultures.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-122-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C122'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Production verbale (orale ou écrite en français) ou non verbale, qui témoigne de l’identification des informations pertinentes par rapport à la tâche, au travers, par exemple, d’un plan, un schéma à annoter, une liste, de phrases simples, d’un résumé en français comprenant les grandes lignes d’une histoire.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-122-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C122'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', 'Production :', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S2-123-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C123'), 'primaire', array['S2']::text[], 'Langue moderne', 'attendu', '• verbale (orale ou écrite en français) qui témoigne de l’identification pertinente des consignes, instructions ou injonctions par rapport à la tâche, au travers, par exemple, d’une liste, de phrases simples, d’un résumé en français comprenant les grandes lignes d’une procédure ; • non verbale en exécution d’une suite limitée de consignes ou d’instructions au travers, par exemple, de mouvements, de manipulations d’objets, de gestes, de déplacements qui témoignent de la compréhension de l’injonction.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
