insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-181-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C181'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'À travers les contenus d’apprentissage retenus pour cette année, l’élève peut construire son identité, la communiquer et découvrir celle d’un autre jeune du même L’élève peut poser progressivement des choix judicieux de manière autonome, afin d’assurer une communication efficace et respectueuse avec l’autre, - malgré quelques erreurs (S-SF-C/LMI S3).', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
