insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-186-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C186'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève prend conscience de la chronologie des évènements et trouve des moyens linguistiques pour les communiquer fidèlement.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-186-2', (select id from public.curriculum_item where version = '2022' and code = 'LM-C186'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'La connotation, inhérente aux différents temps dans la langue cible, donne à l’élève l’occasion de percevoir d’autres manières d’envisager le temps.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-186-3', (select id from public.curriculum_item where version = '2022' and code = 'LM-C186'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'L’élève communique à propos de son environnement et de la réalité qui l’entoure et prend conscience de l’existence de l’environnement dans lequel évolue l’autre.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
