insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-327-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C327'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'et simple constituée enregistré ou en complexité : un et simple constituée de phrases courtes, présentiel support simple d’une de phrases courtes, simples et articulées • longueur et longueur d’environ simples et articulées (6 ou 7 informations complexité : un 50 à 100 mots, en d’environ 60 à 80 différentes par support simple d’une fonction de la nature mots, en fonction de intervenant) longueur globale du message la nature du message d’environ 50 à 100 mots • structure : les informations suivent un ordre logique Pour rencontrer l’attendu, les productions définies ci-dessus peuvent mobiliser plusieurs champs thématiques, s’appuyer sur différents supports et combiner plusieurs structures et intentions de communication.', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
