insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('LM-S3-341-1', (select id from public.curriculum_item where version = '2022' and code = 'LM-C341'), 'primaire', array['S3']::text[], 'Langue moderne', 'attendu', 'B. Formuler des B. Formuler des B. Exécuter hypothèses hypothèses • s’appuyer sur sa • se baser sur sa • prendre le risque connaissance du connaissance du de s’exprimer avec monde monde les ressources linguistiques disponibles • exploiter des indices • sélectionner les • s’appuyer sur des phoniques (voix, mots dont il faut acquis et expériences bruits de fond…) chercher ou vérifier la antérieurs et prosodiques signification dans le (intonation, ton) dictionnaire • exploiter les • exploiter des indices • organiser le message indices non non linguistiques de façon logique linguistiques (gestes, (éléments visuels, mimiques, regards, pictogrammes, type indices visuels, de document, titre, pictogrammes…) sous-titres) • repérer des mots clés • exploiter des indices linguistiques (mots clés)', 'Référentiel de Langues modernes (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Lang-mod-LM.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
