insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P2-3.1-4', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.1'), 'primaire', array['P2']::text[], 'Mathématiques', 'attendu', 'Reconnaitre les nombres de 1 à 100 en s’appuyant sur : - des schèmes structurés mettant en évidence les nombres 2 ou 5 ou 10 ; - des collections différentes de même quantité ; - des variations des positions des objets d’une même collection (invariance/conservation) ; - des variations de l’origine et du sens de comptage des objets d’une même collection (indépendance du cardinal) ; - des représentations en dizaines et unités.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
