insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P2-3.2-15', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P2']::text[], 'Mathématiques', 'attendu', 'Résoudre un problème faisant intervenir des opérations sur les nombres : - en traduisant une situation contextualisée par un dessin, une verbalisation puis l’écriture d’une opération mathématique (+, -, x) ; - en effectuant les calculs ; - en communiquant le résultat avec précision, et verbaliser sa démarche.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
