insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P2-4.1-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P2']::text[], 'Mathématiques', 'attendu', 'Utiliser les mots : - trier : « a ou n’a pas…» (selon le critère défini) ; Ex. : la couleur. - classer (selon des caractéristiques définies au sein d’un critère ; Ex. : rouge, jaune, bleu…', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
