insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P3-4.1-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], 'Mathématiques', 'attendu', 'Utiliser les mots : - trier : « a ou n’a pas …» (selon le critère défini) ; Ex. : la couleur. - classer (selon des caractéristiques définies au sein d’un critère) ; Ex. : rouge, jaune, bleu…', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P3-4.1-2', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], 'Mathématiques', 'attendu', 'Reconnaitre une représentation de données en : - tableau ; - ensembles ; - arbre (dichotomique) ; - diagramme à bandes.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P3-4.1-3', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], 'Mathématiques', 'attendu', 'Collecter des informations à partir d’une question : - exigeant une réponse par oui ou par non ; - permettant un classement des données récoltées.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P3-4.1-4', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], 'Mathématiques', 'attendu', 'Organiser des objets représentés et des données : - par tri selon deux critères considérés successivement ; -par classement selon des caractéristiques déterminées au sein d’un critère.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
