insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P3-4.1-6', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['P3']::text[], 'Mathématiques', 'attendu', 'Choisir, pour organiser des objets représentés : - un critère à appliquer à un tri ; - un critère et au moins deux caractéristiques à appliquer à un classement.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
