insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-1.1-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-1.1'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Utiliser le vocabulaire exprimant des positions absolues : à côté de, contre, à l’intérieur, à l’extérieur, entre, sous, sur, dans, hors, autour de, face à face, dos à dos.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
