insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-2.2-1', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Utiliser et symboliser : - le mètre (m), décimètre (dm), le centimètre (cm), le millimètre (mm), le kilomètre (km), l’hectomètre (hm), le décamètre (dam) ; - le litre (l), le décilitre (dl), le centilitre (cl), millilitre (ml) ; - le kilogramme (kg), le gramme (g), le milligramme (mg) ; - l’euro (€) et les centimes ; - le centimètre carré (cm²), le mètre carré (m²).', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
