insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P4-2.2-16', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P4']::text[], 'Mathématiques', 'attendu', 'Estimer, à l’aide d’étalons non conventionnels, des longues distances (plus de 10 mètres), des capacités, des masses et vérifier son estimation.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
