insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P5-1.2-30', (select id from public.curriculum_item where version = '2022' and code = 'MA-1.2'), 'primaire', array['P5']::text[], 'Mathématiques', 'attendu', 'Utiliser les termes « agrandir », « réduire » pour décrire un mouvement appliqué à une figure.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P5-1.2-31', (select id from public.curriculum_item where version = '2022' and code = 'MA-1.2'), 'primaire', array['P5']::text[], 'Mathématiques', 'attendu', 'Exécuter un mouvement précis donné d’un motif figuratif, avec un support (un gabarit, du papier calque...) pour obtenir son image. Ex. : le glissement sur une droite donnée ou le pivotement d’un demi-tour autour d’un point donné, ou le retournement autour d’un axe donné.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P5-1.2-32', (select id from public.curriculum_item where version = '2022' and code = 'MA-1.2'), 'primaire', array['P5']::text[], 'Mathématiques', 'attendu', 'Désigner parmi des images d’un motif figuratif donné celle qui résulte d’un mouvement donné.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
