insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-3', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Utiliser et symboliser des unités conventionnelles de durées.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
