insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-13', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Lister des objets de la vie courante dont une grandeur se mesure avec l’unité travaillée.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-14', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Donner du sens aux préfixes : déci, centi, milli, kilo, hecto, déca dans les unités conventionnelles travaillées.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-15', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Réaliser des conversions significatives (longueur, masse, capacité, aire, volume) en lien avec les unités conventionnelles travaillées, avec ou sans abaques (construits préalablement).', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-16', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Associer à l’écriture d’une grandeur prélevée dans le quotidien (longueur, capacité, masse, aire, volume), d’autres écritures donnant du sens aux nombres décimaux. Ex. : 20 kg d’engrais pour 400 m², c’est 0,05 kg ou 50 g d’engrais par m².', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-17', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Associer des unités de temps à des durées de situations variées.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-18', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Déterminer et représenter (horloge, chronomètre, ligne du temps…) une durée pouvant dépasser une heure.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-19', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Déterminer un instant d’arrivée ou de départ, à partir d’une durée donnée.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-20', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Rassembler les instruments de mesure nécessaires et organiser judicieusement les prélèvements de mesures pour comparer les résultats.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-21', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Estimer une surface à recouvrir et confronter cette estimation avec les grandeurs mesurées de la surface choisie, en vue de réaliser un achat raisonné.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-22', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Estimer la grandeur d’un objet en référence à une unité conventionnelle choisie avant d’effectuer le mesurage.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-2.2-23', (select id from public.curriculum_item where version = '2022' and code = 'MA-2.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Estimer une durée. Établir l’horaire d’une journée, en organisant les activités choisies parmi celles proposées, selon leurs durées respectives et les durées intermédiaires (repas, pauses, déplacements éventuels…).', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
