insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-3.2-26', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Résoudre un problème faisant intervenir des opérations sur les nombres : -en traduisant une situation contextualisée par un dessin, une verbalisation puis l’écriture d’opérations mathématiques (+, -, x, :) ; - en estimant le résultat ; - en effectuant les calculs ; - en communiquant le résultat avec précision ; - en vérifiant la plausibilité de la réponse, et verbaliser sa démarche.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-P6-3.2-27', (select id from public.curriculum_item where version = '2022' and code = 'MA-3.2'), 'primaire', array['P6']::text[], 'Mathématiques', 'attendu', 'Rédiger un énoncé en partant : - de la communication du résultat ; Ex. : mes parents ont commandé pour 480 € de fournitures. - de maximum trois calculs consécutifs et des résultats. Ex. : 15 l : 1,5 l = 10 10 x 0,25 € = 2,5 € 10 € - 2,5 € = 7,5 €', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
