insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MA-S3-4.1-4', (select id from public.curriculum_item where version = '2022' and code = 'MA-4.1'), 'primaire', array['S3']::text[], 'Mathématiques', 'attendu', 'À partir d’une situation libellée en français, d’une liste de données, d’un tableau de distribution (groupé ou non), d’un diagramme statistique (en bâtonnets, à bandes, circulaire, histogramme) : • décrire la population et la variable statistique étudiées ; • caractériser la variable étudiée (qualitative, quantitative, discrète ou continue) ; • déterminer : - l’effectif total d’une population ; - l’effectif associé à une modalité ou à une classe ; - la fréquence associée à une modalité ou à une classe ; - les effectifs et les fréquences cumulés.', 'Référentiel de Mathématiques (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Mathematiques.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
