insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-101-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C101'), 'maternelle', array['M1', 'M2']::text[], 'Éducation culturelle et artistique', 'attendu', 'Reconnaitre les instruments de musique rencontrés dans le vécu de la classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-102-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C102'), 'maternelle', array['M1', 'M2']::text[], 'Éducation culturelle et artistique', 'attendu', 'S’approprier les termes liés à l’utilisation d’instruments de musique ou d’objets sonores rencontrés dans le cadre scolaire : - frapper (par exemple : percussions avec le corps, des instruments de la classe, des objets divers) ; - souffler (par exemple : le sifflet) ; - frotter (par exemple : le tambourin, le güiro) ; - secouer (par exemple : les maracas).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
