insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-102-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C102'), 'maternelle', array['M3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Montrer et nommer, selon la situation, le geste approprié à l’utilisation d’un instrument de musique ou objets sonores, rencontrés dans le cadre scolaire : - frapper (par exemple : percussions avec le corps, des instruments de la classe, des objets divers) ; -souffler (par exemple : le sifflet) ; - frotter (par exemple : le tambourin, le güiro) ; -secouer (par exemple : les maracas).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
