insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-133-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C133'), 'maternelle', array['M3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Utiliser adéquatement un instrument de musique en : - frappant (par exemple : percussions avec le corps, des instruments de la classe, des objets divers) ; - soufflant (par exemple : le sifflet) ; - frottant (par exemple : le tambourin, le güiro) ; - secouant (par exemple : les maracas).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-134-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C134'), 'maternelle', array['M3']::text[], 'Éducation culturelle et artistique', 'attendu', '- Participer à des jeux vocaux. - Participer à des chants dansés où l’enfant chante tout en réalisant les mouvements. - Pouvoir chanter cinq à sept chansons simples, adaptées aux voix des enfants de 5 à 6 ans. - Jouer avec les paroles : repérer les rimes, marquer les syllabes, exagérer les consonnes, chanter la mélodie sur une voyelle, repérer un phonème…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
