insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-138-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C138'), 'maternelle', array['M3']::text[], 'Éducation culturelle et artistique', 'attendu', 'Reconnaitre et nommer des modes d’expression rencontrés dans le cadre scolaire. Par exemple : le théâtre, les marionnettes, le kamishibai, la danse, la saynète, le mime, des arts du cirque (jonglerie, acrobatie, clownerie…)…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
