insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-262-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C262'), 'maternelle', array['M1', 'M2']::text[], 'Sciences', 'attendu', 'S’approprier, au sein de l’école, des gestes respectueux.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-262-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C262'), 'maternelle', array['M1', 'M2']::text[], 'Sciences', 'attendu', 'Par exemple : - jeter les déchets dans la poubelle ; - respecter les végétaux présents à l’école.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-263-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C263'), 'maternelle', array['M1', 'M2']::text[], 'Sciences', 'attendu', 'Réagir à un besoin physiologique en adoptant l’attitude adéquate : - manger et boire ; - se rendre aux toilettes, se moucher…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-264-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C264'), 'maternelle', array['M1', 'M2']::text[], 'Sciences', 'attendu', 'Désigner et/ou nommer une tenue vestimentaire adéquate en fonction des observations (présence de soleil, de pluie, de neige…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-265-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C265'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Citer au moins un élément qui caractérise un être vivant rencontré dans le vécu scolaire (par exemple : grandir, se nourrir (boire/manger), se reproduire).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-234-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C234'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Désigner et nommer au moins dix parties du corps parmi les suivantes : tête, visage, cou, bras, main, doigt, pouce, dos, ventre, jambe, pied, orteil, épaule, coude, poignet, genou, cheville, bouche, nez, œil, oreille.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-266-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C266'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Désigner et nommer l’organe correspondant à chaque sens : nez, peau, œil, oreille, langue.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-266-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C266'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Dire la fonction de chaque organe : sentir, toucher, voir, entendre, gouter.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-236-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C236'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Exprimer, avec ses mots, en situation, le besoin de respirer, manger, boire, se reposer, dormir, aller aux toilettes, se moucher.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-236-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C236'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Respecter les règles d’hygiène.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-237-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C237'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Nommer son mode de déplacement : marcher ou courir.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-267-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C267'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Utiliser, de manière adéquate, les termes suivants : naitre, grandir, mourir.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-268-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C268'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Désigner, pour les animaux rencontrés dans le vécu scolaire : - au moins une caractéristique physique parmi les suivantes : tête, bouche, yeux ; - d’autres caractéristiques physiques spécifiques : pattes, nageoires, ailes, coquille, plumes, poils, écailles, bec, antennes, queue, sabot, corne…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-239-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C239'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Nommer des animaux rencontrés dans le vécu scolaire.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-269-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C269'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Nommer le(s) mode(s) de déplacement d’animaux rencontrés dans le vécu scolaire (par exemple : marcher, courir, ramper, nager, voler, sauter…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-270-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C270'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Nommer quelques milieux de vie d’animaux rencontrés dans le vécu scolaire (par exemple : la forêt, la mer, la prairie, la mare, la haie…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-236-3', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C236'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Exprimer, avec ses mots, en situation, le besoin de respirer, manger, boire, dormir, s’abriter.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-271-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C271'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Utiliser, de manière adéquate : - les termes suivants : naitre, grandir, œuf, mâle, femelle, petit ; - les termes spécifiques liés aux animaux : poussin, poulain, veau, agneau, chiot, éléphanteau, girafon…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-272-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C272'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Désigner et nommer des végétaux rencontrés dans le vécu scolaire.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-273-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C273'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Désigner et nommer au moins quatre caractéristiques de végétaux rencontrés dans le vécu scolaire parmi les suivantes : feuille, aiguille, tige, racine, fleur, bourgeon, tronc, épine, branche, pétale, fruit.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-274-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C274'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Exprimer, avec ses mots, en situation, au moins deux éléments indispensables au développement de la plupart des végétaux : eau, lumière, air, nourriture puisée dans le sol.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
