insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-296-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C296'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Reformuler, avec ses mots, une question proposée ou exprimer son questionnement relatif à la vie d’un végétal selon son milieu de vie.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-297-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C297'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Dégager des informations relatives à la vie d’un végétal selon son milieu de vie : eau, lumière, air, nourriture puisée dans le sol.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-255-3', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C255'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Exprimer, avec ses mots, les éléments indispensables à la vie d’un végétal selon son milieu de vie.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-298-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C298'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Élaborer, à partir des informations recueillies, un document synthèse (panneau, cahier…) présentant les éléments indispensables à la vie d’un végétal selon son milieu de vie.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-299-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C299'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Observer, dans le cadre du milieu scolaire, la croissance d’un végétal et repérer les indices de son évolution.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-256-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C256'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Observer à l’extérieur et verbaliser des changements visibles de l’arbre selon la saison.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-300-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C300'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Observer et toucher des matières/matériaux rencontrés dans le vécu scolaire pour : - les nommer ; - exprimer une qualité prélevée à l’aide des sens.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
