insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-303-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C303'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Observer, lors de différentes expériences, que l’air se déplace (par exemple : lors de la pression d’une bouteille en plastique, l’air est passé dans le ballon de baudruche fixé au goulot).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-303-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C303'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Expliquer, en situation, avec ses mots, le déplacement de l’air.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
