insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-255-4', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C255'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Exprimer, avec ses mots, des constats posés lors d’observations : - sans lumière, rien n’est visible ; - la lumière traverse certaines matières et pas d’autres ; - la position, la forme et la taille d’une ombre changent.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
