insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-308-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C308'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Repérer et exprimer verbalement et/ou non verbalement : - un geste/une trace de respect de l’environnement (par', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-309-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C309'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'exemple : les déchets sont dans les poubelles et la cour de récréation est propre) ; - un geste/une trace de non-respect de l’environnement (par exemple : des papiers et des boites vides trainent au bord de la route).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-263-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C263'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Réagir à un besoin physiologique en adoptant l’attitude adéquate : - manger et boire ; - respecter des règles d’hygiène ; - se protéger du froid et du soleil ; - se reposer.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-264-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C264'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Exprimer, avec ses mots, le choix de la tenue vestimentaire la plus adéquate en fonction des observations (présence du soleil, de nuages, de pluie, du vent et de la température ressentie).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-310-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C310'), 'maternelle', array['M3']::text[], 'Sciences', 'attendu', 'Utiliser adéquatement les poubelles de la classe réservées aux papiers, aux berlingots, aux bouteilles en plastique, aux restes alimentaires pour permettre le recyclage.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-311-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C311'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Désigner du matériel, des outils de la classe, disponibles et nommés par l’enseignant parmi les catégories suivantes : - des outils utilisés en art, graphisme et bricolage (par exemple : crayon, pinceau, rouleaux de peinture, pot de colle, ciseaux…) ; - des pièces de jeux de construction ; - des types de fermetures (fermeture éclair, velcro, bouton-pression, ceinture, lacets…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-312-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C312'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Désigner des appareils techniques disponibles et nommés par l’enseignant.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-313-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C313'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'S’approprier, en situation, les règles de sécurité dans le cadre de la manipulation d’un objet, d’un outil disponible en classe pour se préserver/se protéger.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-314-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C314'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'S’approprier, en situation, le positionnement adéquat des mains et des doigts dans l’utilisation du matériel, des outils de la classe (par exemple : le pinceau, le crayon, la pince à linge, la fermeture éclair).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-315-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C315'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Désigner les éléments dangereux qui composent les outils utilisés en classe (par exemple : les lames d’une paire de ciseaux).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-315-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C315'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Énoncer les risques potentiels de leur utilisation.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-316-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C316'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Manipuler de manière adéquate le matériel, les outils disponibles en classe pour : - coller, découper, pincer, peindre… - emboiter, encastrer, accrocher… - visser/dévisser, ouvrir/fermer, attacher/détacher.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-317-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C317'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Assembler par emboitement, par encastrement des pièces d’un jeu pour réaliser une construction.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-318-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C318'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Réaliser, dans les jeux symboliques, les gestes appropriés aux éléments utilisés.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-319-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C319'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Repérer un appareil technique disponible, selon la situation (le besoin) pour, par exemple, écouter de la musique, regarder une vidéo.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-320-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C320'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Choisir le matériel approprié et les outils adéquats pour effectuer une réalisation : - manuelle (pâte à sel, plasticine…) ; - technique (pinceau, rouleau, grille, marqueur…) ; - technologique (lampe de poche dynamo…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-321-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C321'), 'maternelle', array['M1', 'M2']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser différents systèmes de fermeture/d’ouverture de vêtements.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-311-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C311'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Reconnaitre du matériel, des outils de la classe, disponibles et en nommer au moins deux, dans chacune des catégories suivantes : - des outils utilisés en art, graphisme et bricolage (par exemple : taille-crayon, agrafeuse, perforatrice, emporte-pièce, pince…) ; - des objets de techniques d’impression ; - des pièces de jeux de construction ; - des types de fermetures (fermeture éclair, velcro, bouton-pression, ceinture, lacets…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-322-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C322'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Reconnaitre des appareils techniques disponibles et en nommer au moins trois.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-313-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C313'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Dire, avec ses mots, des règles de sécurité dans le cadre de la manipulation d’un objet, d’un outil disponible en classe, pour se préserver/se protéger, protéger/préserver les autres.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-313-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C313'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Formuler, si nécessaire, avec l’aide de l’enseignant.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-323-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C323'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Positionner les mains et les doigts de manière adéquate pour utiliser le matériel, les outils de la classe (par exemple : une paire de ciseaux, l’agrafeuse).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-316-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C316'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Manipuler de manière adéquate le matériel, les outils disponibles en classe pour :', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-316-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C316'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', '- agrafer, tailler, coller, découper, perforer, pincer… - imprimer (à l’éponge, à la pomme de terre, avec le doigt…) ; - assembler, emboiter, encastrer, accrocher, équilibrer… - visser/dévisser, ouvrir/fermer, attacher/détacher.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
