insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-324-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C324'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Réaliser, notamment dans les jeux symboliques, les gestes appropriés à l’aide d’un objet technique (vêtements de poupées, poulies, engrenages, gabarit, pochoir…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-319-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C319'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Choisir les appareils techniques disponibles, selon la situation (le besoin) pour, par exemple, photographier, écouter de la musique, regarder une vidéo, enregistrer.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-325-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C325'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Identifier et utiliser de manière adéquate, selon la situation, le matériel et les outils nécessaires à l’activité à réaliser (par exemple : une recette de cuisine, une construction).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-321-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C321'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser différents systèmes de fermeture/d’ouverture des vêtements, des chaussures, ouvrir/fermer son cartable…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-326-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C326'), 'maternelle', array['M3']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser des outils et du matériel adéquat pour réaliser un objet technique (par exemple : un moulin à vent, une manche à air, une maquette, un sablier…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-327-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C327'), 'maternelle', array['M1', 'M2']::text[], 'Formation historique et géographique', 'attendu', 'S’approprier, en situation, des termes : - pour se situer ; - pour (se) placer ; - pour se déplacer.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-328-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C328'), 'maternelle', array['M1', 'M2']::text[], 'Formation historique et géographique', 'attendu', 'Désigner les différents espaces de la classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-329-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C329'), 'maternelle', array['M1', 'M2']::text[], 'Formation historique et géographique', 'attendu', 'Désigner au moins deux éléments d’un paysage observé (par exemple : un arbre dans le bois, une maison dans la rue, une fleur dans le jardin, un pont enjambant la route).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-330-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C330'), 'maternelle', array['M1', 'M2']::text[], 'Formation historique et géographique', 'attendu', 'Utiliser de manière adéquate le terme « maintenant » pour se situer dans le temps.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
