insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-334-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C334'), 'maternelle', array['M1', 'M2']::text[], 'Formation historique et géographique', 'attendu', 'Se déplacer en fonction d’un repère (élément fixe) dans la classe, dans l’espace dédié à la psychomotricité.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
