insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-342-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C342'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Désigner et/ou nommer la maquette, le dessin d’un plan.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-343-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C343'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Citer le nom de l’école et la ville/village où elle se situe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-344-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C344'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'S’approprier et utiliser adéquatement, en situation, des termes : - pour (se) situer dans une journée : avant, maintenant, pendant que, en même temps que, après ; - pour (se) situer dans le temps : maintenant, il y a longtemps ; - pour se situer dans sa famille proche (généalogie).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-345-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C345'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'S’approprier et utiliser adéquatement, en situation, les termes suivants : - le matin, le midi, l’après-midi ; - les repères temporels correspondant aux activités et faits récurrents de la journée d’école (début et fin de journée de classe) ; - les noms des jours de la semaine.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-331-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C331'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Désigner et/ou nommer les représentations du temps utilisées en classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-346-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C346'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Citer au moins deux caractéristiques propres à l’individualité (lieu(x) de vie, âge, prénom, nom de famille).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-347-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C347'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Employer, dans les situations adéquates, des termes qui permettent, de décrire : - la famille, la filiation, la parentalité, l’entourage quotidien ; - les habitudes du cercle familial et/ou social (le sport pratiqué, les associations fréquentées, le voisinage…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-348-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C348'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Nommer des membres du groupe classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-348-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C348'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Citer au moins deux caractéristiques propres à soi et aux autres, selon les habitudes de vie, les habitudes alimentaires…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-349-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C349'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Citer au moins deux caractéristiques des habitudes de vie : - d’ici et d’ailleurs ; - d’aujourd’hui et d’autrefois.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-350-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C350'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Distinguer, dans un espace, les repères fixes des éléments mobiles.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-351-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C351'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Distinguer une représentation de la classe en 3D (maquette) d’une représentation en 2D (dessin d’un plan).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-352-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C352'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Localiser des repères dans la classe, dans l’école, dans l’environnement proche de l’école.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-353-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C353'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', '(Se) placer/(se) situer sur, sous, devant, derrière... un repère (élément fixe).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-334-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C334'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Se déplacer en fonction d’un repère (élément fixe) dans la classe, dans l’école, dans l’environnement proche de l’école.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-354-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C354'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Décrire un déplacement effectué au sein de la classe, de l’école en utilisant au moins deux repères.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-335-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C335'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Identifier au moins deux espaces de la classe, de l’école selon leur fonction (pour jouer, pour lire, pour se détendre, pour manger).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-355-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C355'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Décrire un paysage observé (dans son environnement proche) en identifiant, à minima, trois de ses éléments.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-356-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C356'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Décrire son environnement à différents moments et relever des indices de son évolution : - une modification naturelle ; - une transformation réalisée par l’homme.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
