insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-337-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C337'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Relever selon l’organisation de l’école, les activités et faits récurrents comme repères de temps : - dans la journée (exemple : début et fin des cours) ; - dans la semaine (exemple : période de psychomotricité, congé du samedi et dimanche…).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-358-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C358'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Situer une activité précise en utilisant les termes adéquats (avant-pendant-après) : - par rapport au temps de midi ; - par rapport à un repère déterminé.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-359-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C359'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Situer un fait ou un événement de la journée ou de la semaine sur une représentation du temps utilisée en classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-360-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C360'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Nommer au moins deux activités différentes vécues simultanément par les élèves de la classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-361-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C361'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Placer au moins quatre faits vécus et représentés de façon chronologique, sur une représentation de la journée/de la semaine utilisée en classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-362-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C362'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Relever au moins deux similitudes/deux différences entre un objet courant utilisé actuellement et un objet ancien de même fonction.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-363-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C363'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Se présenter en énonçant au moins deux éléments parmi les suivants : son âge, son prénom, son nom, un lieu de vie.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-364-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C364'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Présenter la famille ou les proches avec qui l’élève partage son quotidien.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-365-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C365'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Comparer au moins deux caractéristiques propres aux habitudes de vie (pour se déplacer, se vêtir, s’alimenter, se divertir…) des élèves de la classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-366-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C366'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'habitudes de vie : - d’aujourd’hui/d’autrefois ; - d’ici/d’ailleurs.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-367-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C367'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Se situer dans le temps et dans l’espace : - en utilisant les termes « avant », « maintenant », « après » ; - en nommant l’activité vécue/à vivre ; - en nommant le lieu où se déroule l’activité. (Par exemple : j’enfile mon manteau dans la classe avant d’aller jouer dans la cour de récréation).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-368-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C368'), 'maternelle', array['M3']::text[], 'Formation historique et géographique', 'attendu', 'Situer un fait/un événement dans le temps et dans l’espace : - en utilisant les termes « avant », « maintenant », « après » ; - en précisant le lieu. (Par exemple : après la récréation, nous irons voir un spectacle dans la salle de gymnastique).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-369-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C369'), 'maternelle', array['M1', 'M2']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Utiliser les formules de politesse et de savoir-vivre, en situation de vie : bonjour, au revoir, s’il vous plait, merci.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-370-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C370'), 'maternelle', array['M1', 'M2']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Utiliser adéquatement le nom des émotions ressenties.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-371-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C371'), 'maternelle', array['M1', 'M2']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Dire, avec ses mots, ce que je peux faire et ce que je ne peux pas faire, selon la situation.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-372-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C372'), 'maternelle', array['M1', 'M2']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Réagir de manière soit verbale, soit non verbale, à une situation vécue.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-373-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C373'), 'maternelle', array['M1', 'M2']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Participer aux tâches et aux activités de la classe, selon son choix, et non en respect d’un classement de celles-ci selon le genre.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-374-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C374'), 'maternelle', array['M1', 'M2']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'S’approprier les formules de politesse en fonction de la situation de communication.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-375-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C375'), 'maternelle', array['M1', 'M2']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Exprimer de manière soit verbale, soit non verbale une émotion vécue et la nommer avec l’aide de l’enseignant.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-376-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C376'), 'maternelle', array['M1', 'M2']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Exprimer de manière soit verbale, soit non verbale un besoin physiologique : boire, manger, dormir, aller aux toilettes, se protéger du froid et de la chaleur, se moucher.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
