insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-407-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C407'), 'maternelle', array['M1', 'M2']::text[], 'Éducation physique', 'attendu', 'Utiliser, en situation vécue, les termes adéquats liés :', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M1-M2-408-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C408'), 'maternelle', array['M1', 'M2']::text[], 'Éducation physique', 'attendu', '- à la perception sensorimotrice : regarder, écouter, souffler, toucher ; - au schéma corporel : les principales parties du corps ; - à la motricité : marcher, courir, ramper ; - à la coordination motrice : tirer, pousser, lancer, prendre, porter…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
