insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-407-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C407'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Utiliser, en situation vécue, les termes adéquats liés :', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-428-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C428'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', '- à la perception sensorimotrice : regarder, écouter, souffler, toucher ; - au schéma corporel : les parties du corps dont certaines articulations ; - à la motricité : marcher, courir, sauter, grimper, glisser, ramper ; - à la coordination motrice : tirer, pousser, lancer, rattraper, shooter, s’arrêter ; - à la notion d’équilibre : marcher en équilibre, se balancer, tomber.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-429-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C429'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Utiliser, en situation vécue, les termes adéquats liés : - à l’espace : courir jusqu’à, s’arrêter à, à l’intérieur de, à l’extérieur de, dedans, dehors, au-dessus, en dessous, à côté de ; - au temps : avant, après, pendant que, en même temps que ; - au rythme : lent, rapide.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-410-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C410'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Désigner, nommer au moins cinq éléments du matériel psychomoteur, utilisé en situation vécue. Par exemple : banc, cerceau, cône, élastique, balle, ballon, tapis.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-430-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C430'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'situation.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-412-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C412'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Énoncer des règles de la psychomotricité pour se préserver/se protéger, protéger/préserver les autres.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-431-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C431'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Montrer, selon la situation, le geste et la posture adéquats pour : - pincer, enfiler, accrocher, empiler, emboiter, visser, dévisser ; - contourner, tracer, écrire ; - découper, tailler, coller, peindre…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-432-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C432'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Effectuer isolément chaque grand mouvement fondamental : marcher, courir, sauter, grimper, glisser, ramper.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-415-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C415'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Effectuer des mouvements avec un objet : tirer, pousser, lancer, rattraper, shooter.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-433-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C433'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Exercer des mouvements et des gestes permettant au corps de rétablir son équilibre.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-434-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C434'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Arrêter son mouvement, son geste au signal ou selon la situation.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-435-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C435'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Réaliser correctement l’enchainement des mouvements et des gestes dictés par l’adulte.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
