insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-437-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C437'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', '- le matériel et sa disposition ; - les pairs (écouter, attendre son tour, encourager).', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-420-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C420'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Appliquer pour se préserver/se protéger, protéger/ préserver les autres, les règles adaptées à l’espace occupé.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-438-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C438'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Exprimer le besoin physiologique de boire, se reposer, aller aux toilettes, se moucher.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-422-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C422'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Exercer, à l’aide d’un matériel varié/d’un outil de la classe, le geste adéquat en adoptant la posture appropriée pour : - pincer, enfiler, accrocher, empiler, emboiter, visser, dévisser ; - contourner, tracer, écrire ; - découper, tailler, coller, peindre…', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-439-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C439'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Effectuer des gestes pour amorcer des graphies : - dans l’espace ; - sur des supports variés à inclinaisons variées ; - avec des objets variés dont des outils scripteurs.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-440-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C440'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Effectuer des mouvements et des gestes lors de la réalisation d’une activité (par exemple : en ateliers, en circuit) : - marcher, courir, ramper, sauter, grimper, glisser ; - tirer, pousser, lancer, rattraper, shooter à l’aide d’un objet ; - rétablir son équilibre.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-441-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C441'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Dire, avec ses mots, tout en le réalisant, l’enchainement de deux mouvements/gestes.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-441-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C441'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Reformuler, si nécessaire, la mise en mots de cet enchainement à l’aide des termes adéquats utilisés par un adulte.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-427-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C427'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Respecter : - le matériel et sa disposition ; - les pairs ; - les règles pour se préserver/se protéger, protéger/ préserver les autres.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-442-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C442'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Adopter une posture adéquate pour effectuer un geste, dont le geste graphique, en tenant correctement un outil scripteur ou d’autres outils de la classe.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-443-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C443'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', '• Une conscience de soi et de l’autre : - confiance en soi, expression • Catégoriser, ordonner et des besoins, des gouts, des modéliser projets • Observer, comparer, raisonner, - droits et devoirs conceptualiser, abstraire - règles de civilité • Exprimer les relations de - comportement, opinions causalité, de temporalité, de personnelles chronologie', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
