insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-445-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C445'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', '- empathie, régulation des • Développer son environnement émotions personnel d’apprentissage - coopération, contestation, (mobiliser un ensemble organisé négociation, décision de ressources et d’outils) - projets, initiatives, stratégie • Conscience des apprentissages : collective - utilité, valeur, pertinence - raisons des choix, communication - autoévaluation, analyse des procédures, autorégulation • Mobiliser des outils numériques', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
