insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-446-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C446'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Découvrir le Développer une monde extérieur pensée critique et le monde du et complexe', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-447-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C447'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'travail • Lutter contre les généralisations (stéréotypes, préjugés) • Appréhender les causalités circu-laires (cercles vicieux ou vertueux) • Trouver, traiter et évaluer des • Découvrir différents milieux pro- sources d’informations : fessionnels (secteurs primaire, - recherche documentaire, fiabilité secondaire, privé, associatif, des informations médias, syndicats…) - organiser les informations (réali- • Identifier/rencontrer des person- sation d’une synthèse) nages emblématiques - référencement et citation des • Comprendre les mécanismes de sources l’économie, au marché et droit - attention sur les traces laissées du travail en ligne • Devenir des consommateurs • Créer des contenus (respect des responsables, faire des choix règles et licences légales) éclairés • Promouvoir le vivre-ensemble • Prendre conscience des (tolérance, respect mutuel, bien-interdépendances mondiales veillance, etc.)', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-448-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C448'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'consciemment, en fonction de leurs activités privilégiées et en y associant d’autres élèves. Dans cette perspective, il est important d’aménager des activités de classe qui vont mener les élèves à devoir poser réellement des choix dans une optique de', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-449-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C449'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'les apprentissages et c’est grâce à la qualité du travail pédagogique dans un environnement serein et sécurisé, ainsi que dans le regard que l’on porte sur lui, que l’élève puise la détermination de son implication.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-449-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C449'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Le rôle de l’enseignant est de l’encourager dans ses efforts, de le confirmer dans une', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-450-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C450'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'L’enfant qui entre à l’école maternelle est encore sujet à l’égocentrisme et au manichéisme de la pensée. La première visée transversale consiste en se connaitre', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-451-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C451'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'soi-même et s’ouvrir aux autres. Ce n’est que lorsque cette ouverture est initiée que la pensée critique peut s’amorcer.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-452-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C452'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'À partir de la troisième maternelle, l’enseignant intervient pour amener chez l’élève une réflexion sur des événements vécus qui ont provoqué chez lui une émotion forte, souvent de colère ou de tristesse. Il s’agit de faire relater les faits en envisageant', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
