insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-453-2', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C453'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'Le jeune enfant ne différencie pas spontanément le naturel et l’artificiel. C’est petit à petit que la part humaine dans les transformations de l’environnement lui apparait dans les actes de son entourage immédiat.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MAT-M3-454-1', (select id from public.curriculum_item where version = '2020' and code = 'MAT-C454'), 'maternelle', array['M3']::text[], 'Éducation physique', 'attendu', 'part de ce qui est nécessaire à la créativité. L’esprit d’entreprendre nécessite la connaissance de l’autre et une confiance en soi telle qu’elle va permettre d’oser faire. Mais aussi d’oser être, de se dévoiler et dès lors, de risquer la critique. Cette aptitude intègre les précédentes et les dépasse.', 'Référentiel des compétences initiales (maternelle, tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2020_REF_Comp-initia-M1M3.pdf)', '2020') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
