insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-21-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C21'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'aliment dont éplucher, découper et prélever une quantité.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-22-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C22'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Sur la base d’une recette en images, énoncer les ingrédients, les étapes, la technique* et les ustensiles utilisés dont ceux destinés à prélever des quantités (cuillère à soupe, cuillère à café, pincée ou autre étalon).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-23-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C23'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Se laver les mains en respectant une procédure.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-24-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C24'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Sur la base d’une recette accompagnée d’images et/ou d’une capsule vidéo, préparer, avec l’aide de l’enseignant, un plat simple ou un aliment constitutif d’un plat, en appliquant la technique* appropriée et en utilisant les ustensiles adéquats.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-25-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C25'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Valoriser un plat, avec l’aide de l’enseignant, au travers d’un dressage soigné.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-26-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C26'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Associer des solides préparés par l’enseignant aux objets qu’ils représentent : murs, portes, fenêtres, mobilier.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-26-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C26'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Réaliser, à l’aide de solides proportionnés préparés par l’enseignant, la maquette d’une salle de classe observée in situ.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
