insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-27-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C27'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Expliquer en quoi les aménagements proposés répondent aux besoins et tiennent compte des contraintes identifiées.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-1-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C1'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, le nom de matériaux*, de matières* dont papier, carton, corde, bois, plastique, fil métallique, verre, sable.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-2-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C2'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, le nom d’outils de mesure dont mètre pliant, mètre roulant.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P2-3-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C3'), 'primaire', array['P2']::text[], 'Formation manuelle et technique', 'attendu', 'Identifier, en fonction de l’ouvrage* à réaliser par les élèves, le nom d’outils, de consommables*, de maintien et de fixation dont agrafeuse, agrafe, marteau, clou, pince coupante, pince à bec.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
