insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-14-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C14'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser rationnellement les consommables* et les énergies.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-15-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C15'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Appliquer la posture ergonomique recommandée par l’enseignant.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-17-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C17'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Nommer des aliments issus d’un circuit court de production, choisis par l’enseignant ; les classer par famille : fruits et légumes, produits laitiers, viandes (ou substituts), poissons, œufs.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-18-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C18'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, dans son cadre d’application*, le vocabulaire spécifique : - aux ustensiles dont balance de cuisine, pot mesureur gradué, minuteur ; - aux techniques* de mesure dont peser ; - aux techniques* de transformation d’aliments dont fouetter, mélanger.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-20-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C20'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Identifier, parmi les aliments utilisés, ceux qui doivent être conservés au réfrigérateur.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-47-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C47'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser l’instrument de mesure adapté à la tâche dont la balance de cuisine, le pot mesureur gradué.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-48-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C48'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Appliquer des gestes techniques* pour transformer un aliment dont fouetter, mélanger.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-22-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C22'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Sur la base d’une recette accompagnée d’une capsule vidéo, énoncer les ingrédients, les étapes, les techniques* et les ustensiles utilisés dont ceux destinés à peser des quantités.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-22-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C22'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Au départ d’une étiquette, d’un emballage mentionnant la provenance et le poids ou calibre d’un aliment, poser un choix, en fonction du plat à réaliser, qui limite le cout, le gaspillage et les impacts écologiques.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-22-3', (select id from public.curriculum_item where version = '2022' and code = 'MT-C22'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Au départ d’une étiquette, d’un emballage mentionnant les consignes de stockage et de conservation d’un aliment, poser les gestes adéquats pour éviter toute détérioration ou tout risque alimentaire.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-24-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C24'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Sur la base d’une recette accompagnée d’images et/ou d’une capsule vidéo, préparer, en sous-groupe et sous la supervision de l’enseignant, un plat simple ou un aliment constitutif d’un plat, en appliquant des techniques* appropriées et en utilisant les ustensiles adéquats.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-25-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C25'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Valoriser un plat, sous la supervision de l’enseignant, au travers d’un dressage soigné.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-1-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C1'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, le nom de matériaux*, de matières* dont caoutchouc, polystyrène, pierre, plâtre, laine, coton.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-2-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C2'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, le nom d’outils de mesure dont règle, mètre ruban.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-3-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C3'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Identifier, en fonction de l’ouvrage* à réaliser par les élèves, le nom d’outils, de consommables*, de maintien et de fixation dont aiguille, pistolet à colle, crochet, tournevis, clé plate, clé à molette, clé Allen, maillet, vis, écrou, pince universelle.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
