insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P4-29-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C29'), 'primaire', array['P4']::text[], 'Formation manuelle et technique', 'attendu', 'Appliquer des gestes techniques* dont mesurer, tracer, coudre, visser, agrafer, coller, enfoncer, clouer, scier.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
