insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P5-33-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C33'), 'primaire', array['P5']::text[], 'Formation manuelle et technique', 'attendu', 'Appliquer des soins aux plants dont tuteurer, ligaturer, tailler.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P5-22-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C22'), 'primaire', array['P5']::text[], 'Formation manuelle et technique', 'attendu', 'Expliquer le mode de mise en œuvre et les conditions de culture, sur la base d’informations techniques visuelles et textuelles fournies et recherchées sur les semis, le plant (calendrier cultural).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P5-34-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C34'), 'primaire', array['P5']::text[], 'Formation manuelle et technique', 'attendu', 'Cultiver, sous la supervision de l’enseignant, un végétal selon un mode de culture défini, en tenant compte du lieu et des conditions de production (substrat, calendrier des semis, température, luminosité, hygrométrie).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-P5-34-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C34'), 'primaire', array['P5']::text[], 'Formation manuelle et technique', 'attendu', 'Aménager un lieu de production, en vue de rencontrer les conditions de réussite de semis ou de plantation.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
