insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S1-3-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C3'), 'primaire', array['S1']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, le nom d’outils, de consommables* et de machines d’usage courant d’assemblage, de maintien et de fixation pour le travail du métal et l’installation des composants d’un circuit électrique simple dont marteau, pince à riveter, rivets, fer à souder, pince à bec, pince à dénuder, clés, tournevis plat, tournevis cruciforme, visseuse, vis, écrou, boulons, étau.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
