insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S1-9-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C9'), 'primaire', array['S1']::text[], 'Formation manuelle et technique', 'attendu', 'Associer les risques et les dangers liés à l’environnement de travail*, aux consommables*, aux outils, aux ustensiles, aux machines et aux techniques*.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S1-10-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C10'), 'primaire', array['S1']::text[], 'Formation manuelle et technique', 'attendu', 'Énoncer les équipements de protection requis, en lien avec l’environnement de travail*, les consommables*, les outils, les ustensiles, les machines et les techniques*.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S1-11-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C11'), 'primaire', array['S1']::text[], 'Formation manuelle et technique', 'attendu', 'Choisir le matériel* et les consommables* parmi ce qui est mis à disposition. Les agencer sur son poste de travail*. Vérifier l’opérationnalité du matériel* (qui peut faire l’objet d’un montage par l’élève).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
