insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S2-27-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C27'), 'primaire', array['S2']::text[], 'Formation manuelle et technique', 'attendu', 'Argumenter les choix d’aménagement permettant de réduire la consommation énergétique et d’améliorer le bien-être, en tenant compte des contraintes identifiées et de l’impact sur la santé et sur l’environnement.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S2-1-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C1'), 'primaire', array['S2']::text[], 'Formation manuelle et technique', 'attendu', 'Utiliser, en fonction de l’ouvrage* à réaliser par les élèves, le nom de matériaux*, de matières* dont textiles naturels (lin, coton) et synthétiques, pierre, céramique, béton, brique.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
