insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S2-10-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C10'), 'primaire', array['S2']::text[], 'Formation manuelle et technique', 'attendu', 'Énoncer les équipements de protection requis, en lien avec l’environnement de travail*, les consommables*, les outils, les ustensiles, les machines et les techniques*.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
