insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-20-3', (select id from public.curriculum_item where version = '2022' and code = 'MT-C20'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Citer les conditions de stockage et de conservation (chaine du froid, taux d’hygrométrie, chaleur, lumière) des aliments utilisés et des préparations réalisées, en vue d’assurer la sécurité sanitaire.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-98-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C98'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Citer les impacts de l’utilisation d’un aliment, en tenant compte de son mode et de son lieu de production (industrie agroalimentaire, circuit court, agriculture biologique), de son conditionnement (préemballé, en conserve, en vrac) et de la saison.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
