insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-164-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C164'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Exemples de contenus ou d’attendus contributifs Cultiver, en autonomie, un végétal selon un mode de culture choisi par l’élève (C, S3).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-164-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C164'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Choisir le matériel et les consommables parmi ce qui est mis à disposition. Les agencer sur son poste de travail. Vérifier l’opérationnalité du matériel (SF, S1- S2-S3).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-165-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C165'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Construire et mettre en service un objet technologique intégrant un circuit électrique simple, incluant le choix d’un capteur utilisé comme interrupteur (C, S1).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-166-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C166'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'alité qui les entoure. Les élèves sont également amenés à prendre conscience, analyser et réguler ces opérations et en particulier à maitriser les principales compétences méthodologiques du « métier d’élève ». Enfin, ils sont incités à développer un environnement personnel d’apprentissage, c’est-à-dire un ensemble organisé de ressources et d’outils physiques et/ou numériques à mobiliser et à agencer pour apprendre.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
