insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-180-4', (select id from public.curriculum_item where version = '2022' and code = 'MT-C180'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'S’orienter repose sur la connaissance de soi, mais aussi sur une découverte du monde extérieur et de l’éventail des possibles qu’il offre en ma-', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-181-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C181'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'tière de filières d’études et de métiers, ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignées à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-182-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C182'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Les apprentissages et découvertes des élèves constitueront des opportunités pour mettre en relation des métiers ou des sphères professionnelles avec les options et les filières d’études de l’après tronc commun, et/ou avec des parcours', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-183-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C183'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'd’études ou de formations et/ou avec des projets personnels. Exemples de métiers à découvrir :', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-184-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C184'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Maraichage, ferme, boucherie, restauration… Architecture (intérieure, extérieure), maçonnerie… Culture, jardinerie, agronomie… Menuiserie, ferronnerie, ingénierie... Électronique, électricité, automatisation…', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-185-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C185'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Programmation… - Communication et collaboration (Compétence, S3) Business process analytic, Lead consultance… - Création de contenus (C, P5 à S3) Réalisation, Webdesign, programmation à… - Sécurité (C, P6-S1) Architecture de projet informatique, security officer…', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-185-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C185'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Identifier des personnages emblématiques (contemporains ou non) dans leur domaine ainsi que leurs parcours peut constituer une source d’inspiration ou de motivation et peut contribuer à éclairer les élèves sur leur future orientation.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-185-3', (select id from public.curriculum_item where version = '2022' and code = 'MT-C185'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Cette démarche amène à comprendre la manière dont les métiers manuels et d’ingénierie imposent une évolution dans la façon de se former et de construire des connaissances qui évoluent avec le temps.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-185-4', (select id from public.curriculum_item where version = '2022' and code = 'MT-C185'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Des personnages liés à ces métiers font partie intégrante de l’Histoire (par exemple : John Cockerill, Zénobe Gramme, Ernest Solvay, Henri Maus, Katherine Johnson, Dorothy Vaughan, Mary Jackson, Ada Lovelace, Mark Zuckerberg, Bill Gates…).', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-185-5', (select id from public.curriculum_item where version = '2022' and code = 'MT-C185'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Relevant davantage d’un savoir-agir, il s’agit ici pour l’élève de rassembler,', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-186-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C186'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'd’articuler et d’incarner ce qu’il a appris sur lui-même et sur les autres, ce qu’il a appris du monde scolaire, de la diversité des filières et options scolaires qui', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-187-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C187'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 's’ouvrent après le tronc commun et ce qu’il connait du monde des activités professionnelles, de manière à se forger une vision de l’avenir et à se mettre en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, gouts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à « construire leur vie ». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-188-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C188'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Exemples d’opportunités offertes par le référentiel Le développement de cette capacité à pouvoir agir peut être travaillé via la prise de conscience par l’élève de l’impact de ses comportements quotidiens sur sa santé, sa sécurité et son environnement.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-189-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C189'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'Une prise de conscience des proportions filles/garçons qui s’orientent dans certaines filières technologiques et des raisons de ce phénomène contribue à modifier les tendances observées.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-190-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C190'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'La découverte du monde technologique et du monde numérique, ainsi que leur fonctionnement, doit inciter les élèves à réfléchir et à poser des choix en termes de poursuite de leur parcours après le tronc commun vers des filières technologiques et/ou numériques, en toute connaissance.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-191-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C191'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'La perpétuelle évolution des technologies et du numérique et l’impact des innovations qui en découlent sur la société, tant au niveau du développement économique que social, peuvent faire émerger chez les élèves, une envie de participer à cet essor en devenant eux-mêmes des acteurs de changement.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-192-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C192'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'La connaissance de la diversité des métiers et des filières scolaires ainsi que celle des métiers en émergence ouvrent, à tous, des perspectives de choix et de réorientations éventuelles, tout au long du parcours de vie.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-193-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C193'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'L’ancrage des connaissances technologiques dans l’actualité et dans le vécu des élèves permet de donner du sens à celles-ci dans la société, sur le marché du travail et d’utiliser des arguments en faveur d’un choix de formation.', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-194-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C194'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'P3 Trier, avec l’aide de l’enseignant, dans leur cadre de Organiser des objets représentés et des données : production, les déchets recyclables, compostables, - par tri selon deux critères considérés', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-194-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C194'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'récupérables. (SF, Commun aux différents champs) successivement ; - par classement selon des caractéristiques déterminées au sein d’un critère. (SF)', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-195-1', (select id from public.curriculum_item where version = '2022' and code = 'MT-C195'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'S1 Concevoir et réaliser un(des) ouvrage(s) en Concevoir une production plastique, à partir de', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('MT-S3-195-2', (select id from public.curriculum_item where version = '2022' and code = 'MT-C195'), 'primaire', array['S3']::text[], 'Formation manuelle et technique', 'attendu', 'choisissant les outils, les consommables et les techniques, de gestes et de concepts artistiques. techniques adaptés. (C, Matières et matériaux) (C) Nommer des propriétés de matériaux et de Identifier expérimentalement des échantillons de matières dont conducteur (électrique, thermique), métaux, sur la base de leurs propriétés physiques isolant, inoxydable, malléable, transparent, (malléabilité, conductivité électrique, thermique, élastique. (S, Matières et matériaux) éclat). (SF)', 'Référentiel de Formation manuelle, technique, technologique et numérique (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Manu-techn-FMTTN.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
