insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('PC-S3-86-1', (select id from public.curriculum_item where version = '2022' and code = 'PC-C86'), 'primaire', array['S3']::text[], 'Éducation à la philosophie et à la citoyenneté', 'attendu', 'Développer une pensée critique et complexe requiert de recourir à des catégories d’analyse multiples pour lutter contre les généralisations, de développer une appréhension des causalités circulaires ainsi que de trouver, traiter et évaluer des sources d’informations fiables, quel qu’en soit le support, y compris numérique.', 'Référentiel d''Éducation à la philosophie et à la citoyenneté (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Educa-Philo-EPC.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
