insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-C439', (select id from public.curriculum_item where version = '2022' and code = 'SC-0'), 'primaire', array['S3']::text[], 'Sciences', 'competence', 'Citer des comportements de protection face aux dangers liés à la lumière trop intense et à l’usage de rayons LASER. (SF) Proposer et expliquer des comportements appropriés pour se protéger, en établissant un lien entre le son/la lumière et les organes qui les perçoivent. (C) Mettre en évidence des impacts de notre mode de vie sur la gestion de l’eau et énoncer des gestes et des actions permettant de préserver les ressources en eau. (C) Repérer des situations de bruits trop intenses dans le vécu d’école et énumérer un ensemble de précautions à prendre pour éviter des sons trop', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
