insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-108-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-C108'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Expliciter la nécessité de s’alimenter pour produire de la matière et de l’énergie.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-109-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C109'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Énoncer quelques règles d’hygiène de vie : - alimentation saine (variée et adaptée aux besoins) ; - nécessité de boire de l’eau ; - activité physique régulière ; - sommeil.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
