insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-130-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C130'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Énoncer qu’un mouvement peut être commandé par le cerveau et que l’information circule par les nerfs. Préciser que pour qu’il y ait un mouvement d’un membre, il faut que le muscle soit au moins attaché à deux os par des tendons.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P4-130-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-C130'), 'primaire', array['P4']::text[], 'Sciences', 'attendu', 'Identifier que lorsqu’il y a une mise en mouvement, un changement dans le mouvement ou un changement de la forme d’un objet, il y a une force qui s’exerce sur l’objet.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
