insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-13-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C13'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'S’exprimer de manière structurée en utilisant une terminologie appropriée à la situation.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-13-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-C13'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'Réaliser une trace relative au questionnement de départ, au déroulement de la démarche et à la conclusion en utilisant le support le plus adéquat (dessin, maquette, photo, panneau, rapport d’expérience...).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-165-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C165'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'Décrire le fonctionnement du système respiratoire : - situer les principaux organes du système respiratoire (nez, bouche, trachée, bronches, poumons, alvéoles) ; - décrire les rôles du diaphragme et de la cage thoracique lors des mouvements ventilatoires ; - décrire les échanges gazeux avec le sang : dioxygène et dioxyde de carbone au niveau des alvéoles.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-166-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C166'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'Décrire le fonctionnement du système digestif : - situer les principaux organes du système (bouche, œsophage, estomac, intestin grêle, côlon, anus et les glandes annexes : glandes salivaires, pancréas et foie) ; - préciser que la plupart des aliments sont transformés en nutriments, avant d’être absorbés au niveau de l’intestin grêle et ainsi passer dans le sang ; - préciser que l’eau est absorbée au niveau du côlon ; - préciser que les matières non absorbées sont évacuées au niveau de l’anus.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-167-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C167'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'Expliquer le rôle du cœur, des différents types de vaisseaux (veines et artères) et du sang.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-P6-168-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C168'), 'primaire', array['P6']::text[], 'Sciences', 'attendu', 'Préciser que les nutriments, le dioxygène et le dioxyde de carbone sont transportés dans l’organisme par le sang.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
