insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-253-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-C253'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Analyser des informations pour expliquer des causes et des conséquences d’une grande extinction d’espèces.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
