insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-255-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C255'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Expliquer, à partir d’un arbre phylogénétique, que des animaux d’une collection donnée ont des liens de parenté et partagent des ancêtres communs.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-256-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C256'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Citer des activités humaines ayant un impact positif et des activités humaines ayant un impact négatif sur un écosystème (dont au moins, l’aménagement du territoire, la création de réserves naturelles, la pollution et l’exploitation excessive d’une ressource naturelle).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S2-17-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C17'), 'primaire', array['S2']::text[], 'Sciences', 'attendu', 'Utiliser les termes : pollution, réserve naturelle.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
