insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-352-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C352'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Situer les travaux d’Antoine Laurent de Lavoisier et Marie- Anne Pierrette Paulze dans leur contexte historique. Énoncer la loi de conservation de la masse et l’expliquer à l’aide de la conservation de la matière au niveau moléculaire (nombres d’atomes conservés).', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
