insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-1-4', (select id from public.curriculum_item where version = '2022' and code = 'SC-C1'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'S’orienter repose sur la connaissance de soi, mais aussi sur une découverte du monde extérieur et de l’éventail des possibles qu’il offre en ma-', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-410-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C410'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'tière de filières d’études et de métiers ainsi que de liens entre filières et métiers. C’est aussi établir des relations entre les savoirs, savoir-faire et compétences enseignées à l’école et les grandes sphères de l’activité professionnelle et humaine de manière plus générale. Il s’agit, pour les élèves, de découvrir les mondes professionnel et scolaire dans leurs composantes et leur organisation, les liens qu’ils entretiennent avec la société et ses évolutions, et de réfléchir au sens qu’ils revêtent à leurs yeux.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-387-7', (select id from public.curriculum_item where version = '2022' and code = 'SC-C387'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Exemples d’opportunités offertes par le référentiel', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-411-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C411'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Les thèmes suivants seront des occasions de découvrir une diversité de métiers : - Son et lumière (S, P3) : techniques du cinéma, médecine, optique… - Alimentation (S, P4) : agriculture, boulangerie, fromagerie… - Pollinisation (S, P5) : apiculture, horticulture… - Environnement (S, S1) : sylviculture, ornithologie, guide nature, activités en lien avec des secteurs d’activités tels que traitement des déchets, recyclage, traitement de l’eau…', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-412-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C412'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', '- Moyens contraceptifs et protection contre les IST (S, S1) : médecine, secteurs sociaux et infirmiers… activités en lien avec des secteurs d’activités tels que les industries de la chimie, du vivant, pharmaceutique… La découverte de personnages emblématiques (contemporains ou non) dans', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-413-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C413'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'leur domaine ainsi que leurs parcours peut constituer une source d’inspiration ou de motivation et peut contribuer à éclairer les élèves sur leur future orientation. « Apprendre à propos des sciences » amène par ailleurs à comprendre la manière dont les scientifiques travaillent et construisent des connaissances qui évoluent avec le temps (exemples de personnages : Charles Darwin, Archimède, Dimitri', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-414-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C414'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Mendeleïev, Isaac Newton, Marie Curie, Antoine Laurent de Lavoisier et Marie- Anne Pierrette Paulze… et des scientifiques contemporains liés à des questions d’actualité). Les apprentissages et découvertes des élèves constitueront des opportunités pour mettre en relation des métiers ou des sphères professionnelles avec les options et filières d’études de l’après tronc commun, et/ou avec des parcours d’études ou de formations et/ou avec des projets personnels.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-1-5', (select id from public.curriculum_item where version = '2022' and code = 'SC-C1'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Relevant davantage d’un savoir-agir, il s’agit ici pour l’élève de rassembler, d’articuler et d’incarner ce qu’il a appris sur lui-même et sur les autres, ce qu’il', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-415-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C415'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'a appris du monde scolaire, de la diversité des filières et options scolaires qui s’ouvrent après le tronc commun et ce qu’il connait du monde des activités', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-416-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C416'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'professionnelles, de manière à se forger une vision de l’avenir et à se mettre en projet. Sur la base d’une identification de plus en plus claire et du développement progressif de leurs intérêts, goûts, et domaines privilégiés de compétences, les élèves apprennent à élaborer peu à peu un projet, de formation, d’études et de vie ; ils apprennent à « construire leur vie ». Il s’agit aussi de les sensibiliser à l’importance de disposer de plusieurs scénarios d’avenir et de concevoir la sélection progressive de l’un d’entre eux comme un processus dynamique, évolutif, non figé.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-387-8', (select id from public.curriculum_item where version = '2022' and code = 'SC-C387'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Exemples d’opportunités offertes par le référentiel', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-417-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C417'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Le développement de cette capacité à pouvoir agir peut être travaillé via la prise de conscience par l’élève de l’impact de ses comportements quotidiens sur sa santé, la sécurité et sur l’environnement.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-418-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C418'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Une prise de conscience des proportions filles/garçons qui s’orientent dans certaines filières « sciences et technologies » et des raisons de ce phénomène contribue à modifier les tendances observées.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-419-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C419'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', '« Apprendre à propos des sciences » contribue à la compréhension des modalités de construction des connaissances scientifiques et des caractéristiques de la pensée scientifique.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-419-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-C419'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'La découverte du monde scientifique et de son fonctionnement doit inciter les élèves à réfléchir et à poser des choix, en toute connaissance, en termes de poursuite de leur parcours après le tronc commun vers des filières scientifiques.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-420-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C420'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'La perpétuelle évolution des sciences et technologies et l’impact du développement des sciences et des innovations technologiques qui en découlent sur la société, (que ce soit en termes de santé ou de développement économique et social) peuvent faire émerger chez les élèves une envie de participer à cet essor en devenant eux-mêmes des acteurs de changement.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-421-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C421'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'La connaissance de la diversité des métiers et des filières scolaires ainsi que celle des métiers en émergence ouvrent à tous des perspectives de choix et de réorientations éventuelles, tout au long du parcours de vie.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-422-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C422'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'L’ancrage des connaissances scientifiques dans l’actualité et dans le vécu des élèves permet de donner du sens à celles-ci dans la société, sur le marché du travail et d’utiliser des arguments en faveur d’un choix de formation.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-422-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-C422'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Le savoir-faire transversal « analyser et débattre » outille les élèves à cette argumentation.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-423-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C423'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Organiser des objets réels ou représentés :', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-423-2', (select id from public.curriculum_item where version = '2022' and code = 'SC-C423'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', '- par tri selon un critère déterminé ; - par classement selon maximum trois', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-424-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C424'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'caractéristiques déterminées au sein d’un critère.', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
insert into public.curriculum_item (code, parent_id, level, grades, subject, kind, label, source, version) values ('SC-S3-425-1', (select id from public.curriculum_item where version = '2022' and code = 'SC-C425'), 'primaire', array['S3']::text[], 'Sciences', 'attendu', 'Réaliser les actions : manipuler, propulser, déplacer,', 'Référentiel de Sciences (tronc commun) (https://www.enseignement.be/fileadmin/portail_age/uploads/parcours_apprentissage/maternel_primaire_ordinaire/Organisation/Contenus_apprentissages_Maternel_Primaire/Referentiels/2022_REF_Sciences.pdf)', '2022') on conflict (version, code) do update set parent_id = excluded.parent_id, level = excluded.level, grades = excluded.grades, subject = excluded.subject, kind = excluded.kind, label = excluded.label, source = excluded.source;
